  var val   = flip(valProb(price)); // valence = true/false

  // Marginalise over QUD (uniform) and theta (uniform over price grid)
  var prob = 0;
  for (var t = 0; t < priceGrid.length; t++) {
    var theta = priceGrid[t];
    prob += probSpeakerExpensive(price, val, theta);
  }
  prob = prob / priceGrid.length; // average over theta

  factor(Math.log(prob)); // condition on the observed utterance "expensive"
  return {price: price, valence: val};
};

