var pricePriorProb = [0.8070, 0.1070, 0.0434, 0.0223, 0.0203];
var valenceProbByPrice = [0.3173, 0.7920, 0.8933, 0.9524, 0.9864];

var cost = { expensive: 0, notExpensive: 1 };

// truth condition for each utterance
function truth(utter, price, theta) {
  if (utter === 'expensive') return price >= theta;
  else return price <= theta; // notExpensive
}

// score of the literal listener: probability of the correct QUD answer
function literalScore(priceTrue, valenceTrue, utter, theta, QUD) {
  var validPrices = [];
  for (var i = 0; i < priceGrid.length; i++) {
    if (truth(utter, priceGrid[i], theta)) validPrices.push(priceGrid[i]);
  }
  var m = validPrices.length;
  if (m === 0) return 0; // should not happen
  var priceIdxTrue = priceGrid.indexOf(priceTrue);
  var probPriceTrue = validPrices.indexOf(priceTrue) >= 0 ? 1 / m : 0;
  var sumVTrue = 0;
  for (var k = 0; k < validPrices.length; k++) {
    sumVTrue += valenceProbByPrice[priceGrid.indexOf(validPrices[k])];
  }
  var probValTrue = sumVTrue / m;
  var probBoth = 0;
  if (validPrices.indexOf(priceTrue) >= 0) {
    probBoth = valenceProbByPrice[priceIdxTrue] / m;
  }

  if (QUD === 0) return probPriceTrue;            // price only
  if (QUD === 1) return probValTrue;             // valence only
  return probBoth;                               // both
}

// speaker chooses an utterance given the true state
function speakerProb(priceTrue, valenceTrue) {
  var totalExp = 0;
  var totalNe = 0;
  var uq = 1 / 3;    // prior over QUD
  var thPrior = 1 / priceGrid.length; // prior over theta

  for (var q = 0; q < 3; q++) { // QUD: 0-price,1-valence,2-both
    for (var t = 0; t < priceGrid.length; t++) { // theta
      var theta = priceGrid[t];

      var scoreExp = literalScore(priceTrue, valenceTrue, 'expensive', theta, q);
      var scoreNe = literalScore(priceTrue, valenceTrue, 'notExpensive', theta, q);

      var weightExp = Math.exp(scoreExp - cost.expensive); // cost 0
      var weightNe = Math.exp(scoreNe - cost.notExpensive); // cost 1

      var denom = weightExp + weightNe;
      var probExp = weightExp / denom;
      var probNe = weightNe / denom;

      totalExp += uq * thPrior * probExp;
      totalNe += uq * thPrior * probNe;
    }
  }
  return { expensive: totalExp, notExpensive: totalNe };
}

