  return map(function(s) { return Math.exp(Gaussian({mu: mu, sigma: sigma}).score(s)); }, stateValues);
};

// Superordinate and subordinate height distributions (normalized)
var superordinateProbs = getProbs(0, 1);
var subordinateProbs = getProbs(1, 0.5);

var normalize = function(probs) {
  var Z = sum(probs);
  return map(function(p) { return p / Z; }, probs);
};

var superordinateDist = Categorical({ps: normalize(superordinateProbs), vs: stateValues});
var subordinateDist = Categorical({ps: normalize(subordinateProbs), vs: stateValues});

var comparisonClasses = ["superordinate", "subordinate"];

var alpha = 5;

// Literal listener: given utterance, threshold, comparison class, returns distribution over states
var literalListener = function(utt, tallThresh, shortThresh, compClass) {
  var stateDist = (compClass === "superordinate") ? superordinateDist : subordinateDist;
  return Infer({method: 'enumerate'}, function() {
    var state = sample(stateDist);
    var uttTrue = (utt === 'tall') ? (state > tallThresh) :
                  (utt === 'short') ? (state < shortThresh) :
                  true; // silence
    condition(uttTrue);
    return state;
  });
};

// Speaker: given state, tallThresh, shortThresh, compClass, chooses utterance
var speaker = function(state, tallThresh, shortThresh, compClass) {
  return Infer({method: 'enumerate'}, function() {
    var utt = uniformDraw(['tall', 'short', 'silence']);
    var llDist = literalListener(utt, tallThresh, shortThresh, compClass);
    var llProb = Math.exp(llDist.score(state));
    factor(alpha * Math.log(llProb));
    return utt;
  });
};

// Pragmatic listener: hears 'tall', infers state, thresholds, comparison class
var pragmaticListener = function(utt) {
  return Infer({method: 'enumerate'}, function() {
    var tallThresh = uniformDraw(tallThresholds);
    var shortThresh = uniformDraw(shortThresholds);
    var compClass = uniformDraw(comparisonClasses);
    var stateDist = (compClass === "superordinate") ? superordinateDist : subordinateDist;
    var state = sample(stateDist);
    var speakerUttDist = speaker(state, tallThresh, shortThresh, compClass);
    observe(speakerUttDist, utt);
    return compClass;
  });
};

