  method: 'MCMC',
  samples: 1000,
}, model);

function model() {
  var binParam = 3;
  var STATES = [];
  for (var i = 0; i < 18; i++) {
    STATES.push(-3 + i / binParam);
  }

  var mu_super = 0, sigma_super = 1;
  var mu_sub = 1, sigma_sub = 0.5;

  var comparisonClass = sample(Categorical([0.5, 0.5]), ["superordinate", "subordinate"]);
  var tallThreshold = uniformDraw(uniform(-3, 3));
  var shortThreshold = uniformDraw(uniform(-3, 3));

  var mu = comparisonClass === "superordinate" ? mu_super : mu_sub;
  var sigma = comparisonClass === "superordinate" ? sigma_super : sigma_sub;

  var logWeight = 0;
  for (var i = 0; i < STATES.length; i++) {
    var s = STATES[i];
    var pdf = Math.exp(-0.5 * Math.pow(s - mu, 2) / sigma**2);
    if (s > tallThreshold) {
      logWeight += Math.log(pdf);
    }
  }

  condition(logWeight > 0);
  return comparisonClass;
}

var binParam = 3;
var stepSize = 1 / binParam; // 1/3
var states = mapN(function(k) { return -3 + k * stepSize; }, 18);

var gaussianPDF = function(mu, sigma, x) {
  return Math.exp(-0.5 * Math.pow((x - mu) / sigma, 2)) / (sigma * Math.sqrt(2 * Math.PI));
};

var normalize = function(ps) {
  var total = sum(ps);
  return map(function(p) { return p / total; }, ps);
};

var superProbs = normalize(map(function(s) { return gaussianPDF(0, 1, s); }, states));
var subProbs   = normalize(map(function(s) { return gaussianPDF(1, 0.5, s); }, states));

var tallThresholds  = map(function(s) { return s - 1 / (2 * binParam); }, states);
var shortThresholds = map(function(s) { return s + 1 / (2 * binParam); }, states);

var utterances = ['tall', 'short', 'silence'];
var alpha = 5;

var meaning = function(utt, state, tauTall, tauShort) {
  if (utt === 'tall')    return state > tauTall;
  if (utt === 'short')   return state < tauShort;
  if (utt === 'silence') return true;
};

var literalListener = cache(function(utt, tauTall, tauShort, cc) {
  return Infer({method: 'enumerate'}, function() {
    var ps = cc === 'superordinate' ? superProbs : subProbs;
    var state = categorical({vs: states, ps: ps});
    condition(meaning(utt, state, tauTall, tauShort));
    return state;
  });
});

var speaker = cache(function(state, tauTall, tauShort, cc) {
  return Infer({method: 'enumerate'}, function() {
    var utt = uniformDraw(utterances);
    var L0 = literalListener(utt, tauTall, tauShort, cc);
    factor(alpha * L0.score(state));
    return utt;
  });
});

var pragmaticListener = function(observedUtt) {
  return Infer({method: 'enumerate'}, function() {
    // Entity is a basketball player: state drawn from subordinate prior
    var state   = categorical({vs: states, ps: subProbs});
    var tauTall  = uniformDraw(tallThresholds);
    var tauShort = uniformDraw(shortThresholds);
    var cc       = uniformDraw(['superordinate', 'subordinate']);
    var S = speaker(state, tauTall, tauShort, cc);
    observe(S, observedUtt);
    return cc;
  });
};

