// Valence prior given state: prob of -1
var valNegProb = {
  "terrible":0.99,
  "bad":0.90,
  "ok":0.50,
  "good":0.09,
  "amazing":0.01
};

// Arousal priors (unnormalized weights) given state
var arousalWeightMap = {
  "terrible":[1,10,30,45,50],
  "bad":[1,5,25,40,45],
  "ok":[50,45,30,10,1],
  "good":[1,5,25,40,45],
  "amazing":[1,10,30,45,50]
};
var arousalProbsMap = {};
states.forEach(function(s){
  var w = arousalWeightMap[s];
  var sum = w.reduce(function(a,b){return a+b;});
  arousalProbsMap[s] = w.map(function(v){ return v/sum; });
});

// Literal listener (not needed explicitly, utility is derived from its behaviour)
function utility(state, valence, arousal, goal, utter){
  if (goal === "goalState"){
    return (state === utter) ? 1 : 0;
  }else if (goal === "goalValence"){
    var pNeg = valNegProb[utter];
    var prob = (valence === -1) ? pNeg : (1 - pNeg);
    return prob;
  }else if (goal === "goalArousal"){
    var probs = arousalProbsMap[utter];
    // find index of the actual arousal value
    var idx = arousalVals.indexOf(arousal);
    return probs[idx];
  }
  return 0;
}

// Model
var model = function(){
  // sample state
  var stateIdx = sample(Categorical({ps: stateProbs}));
  var state = states[stateIdx];

  // sample valence
  var isNeg = flip(valNegProb[state]);
  var valence = isNeg ? -1 : 1;

  // sample arousal
  var arousalIdx = sample(Categorical({ps: arousalProbsMap[state]}));
  var arousal = arousalVals[arousalIdx];

  // sample goal uniformly
  var goal = uniformDraw(goals);

  // observed utterance
  var utter = "terrible";

  // speaker utility (proportional to likelihood of utterance)
  var u = utility(state, valence, arousal, goal, utter);
  // condition on the utterance having been produced
  if (u <= 0){
    factor(-Infinity); // zero probability
  }else{
    factor(Math.log(u)); // proportional to utility
  }

  return {state: state, valence: valence, arousal: arousal};
};

