var ANSWER = Infer({method:"enumerate"}, function() {
  // Constants
  var STATE_LABELS = ["terrible","bad","ok","good","amazing"];
  var AROUSAL_VALUES = [0.1,0.3,0.5,0.7,0.9];
  var NEG_PROB = {"terrible":0.99,"bad":0.90,"ok":0.50,"good":0.09,"amazing":0.01};
  var AROU_UNNORM = {
    "terrible":[1,10,30,45,50],
    "bad":[1,5,25,40,45],
    "ok":[50,45,30,10,1],
    "good":[1,5,25,40,45],
    "amazing":[1,10,30,45,50]
  };

  // Helper: sum of array
  var sum = function(arr){ return arr.reduce(function(a,b){return a+b;},0); };

  // valence weight given state and valence
  var valenceWeight = function(state,valence) {
    var pNeg = NEG_PROB[state];
    return (valence===-1) ? pNeg : (1-pNeg);
  };

  // arousal weight given state and arousal
  var arousalWeight = function(state,arousal) {
    var probs = AROU_UNNORM[state];
    var idx = AROUSAL_VALUES.indexOf(arousal);
    var total = sum(probs);
    return probs[idx] / total;
  };

  // Speaker utterance weights
  var getWeights = function(state,valence,arousal,goal) {
    var weights = [];
    for (var i=0;i<STATE_LABELS.length;i++) {
      var label = STATE_LABELS[i];
      var w = 0;
      if (label===state) {
        if (goal==="goalState") w = 1;
        else if (goal==="goalValence") w = valenceWeight(state,valence);
        else if (goal==="goalArousal") w = arousalWeight(state,arousal);
      }
      weights.push(w);
    }
    return weights;
  };

  // World priors
  var state = sample(Categorical({ps:[1,5,40,40,40], values:STATE_LABELS}));
  var pNeg = NEG_PROB[state];
  var valence = sample(Bernoulli({p:pNeg})) ? -1 : 1;

  var probs = AROU_UNNORM[state];
  var total = sum(probs);
  var normPs = probs.map(function(x){ return x/total; });
  var arousalIdx = sample(Categorical({ps:normPs}));
  var arousal = AROUSAL_VALUES[arousalIdx];

  // Goal prior
  var goal = sample(Categorical({ps:[1,1,1], values:["goalState","goalValence","goalArousal"]}));

  // Speaker utterance
  var weights = getWeights(state,valence,arousal,goal);
  var utterance = sample(Categorical({ps:weights, values:STATE_LABELS}));

  // Observation
  condition(utterance === "terrible");

  // Return joint
  return {state:state, valence:valence, arousal:arousal};
});

