  child:       categorical({ps: weightVals.map(function(v){return gauss(v,0.5,1);}), vs: weightVals}),
  adult:       categorical({ps: weightVals.map(function(v){return gauss(v,2,3);}),   vs: weightVals}),
  bodybuilder: categorical({ps: weightVals.map(function(v){return gauss(v,5,3);}),   vs: weightVals})
};

