  // 1. Sample comparison class from prior
  var compClass = sample(compPrior);
  // 2. Sample weight from the class‑specific distribution
  var w = sample(weightDist[compClass]);
  // 3. Sample thresholds uniformly
  var thrH = uniformDraw(heavyThreshVals);
  var thrL = uniformDraw(lightThreshVals);
  // 4. Speaker chooses utterance proportionally to exp(alpha * literal listener score)
  var scores = utterances.map(function(u){
    return Math.exp(alpha * meaningProb(u,w,thrH,thrL));
