// Helper: Gaussian density discretized over provided values
function gaussianDist(mu, sigma, vals) {
  var unnorm = vals.map(v => Math.exp(-Math.pow(v - mu, 2) / (2 * sigma * sigma)));
  var sum = unnorm.reduce((a, b) => a + b, 0);
  var probs = unnorm.map(p => p / sum);
  return Categorical({ labels: vals, probs: probs });
}

