  var thH = sample(Categorical({ labels: heavyTS, probs: Array(30).fill(1 / 30) }));
  var thL = sample(Categorical({ labels: lightTS, probs: Array(30).fill(1 / 30) }));

  // Speaker model: probability of uttering "heavy" given weight and thresholds
  var alpha = 5;
  var logPHeavy = alpha * Math.log(pMeaning("heavy", w, thH, thL));
  var logPLight = alpha * Math.log(pMeaning("light", w, thH, thL));
  var logZ = Math.log(Math.exp(logPHeavy) + Math.exp(logPLight));
  var probHeavy = Math.exp(logPHeavy - logZ);

  // Condition on hearing "heavy"
  factor(Math.log(probHeavy));

  // Return the inferred weight
  return w;
}

