var alpha = 3;

// Helper: does an utterance describe a given object?
function matches(obj, utt){
  var parts = utt.split(" ");
  if (parts.length === 1) {
    // bare type
    var type = parts[0];
    return obj.split(" ")[1] === type;
  } else {
    // color + type
    var color = parts[0];
    var type  = parts[1];
    var objParts = obj.split(" ");
    return objParts[0] === color && objParts[1] === type;
  }
}

// Helper: number of words in an utterance (cost)
function cost(utt){
  return utt.split(" ").length;
}

// Literal listener score: probability the listener picks the target
// given that it draws uniformly from objects compatible with the utterance.
function literalScore(target, utt){
  // find all objects in the shared context compatible with the utterance
  var compatible = shared.filter(function(o){ return matches(o, utt); });
  if (compatible.length === 0) return 0;
  // if the target itself is compatible, success prob = 1/|compatible|
  if (matches(target, utt)){
    return 1 / compatible.length;
  } else {
    return 0;
  }
}

// Speaker distribution over utterances given a target object
function speakerDist(target){
  // compute unnormalized weights for each utterance
  var weights = utterances.map(function(u){
    var util = alpha * literalScore(target, u) - cost(u);
    return Math.exp(util);
  });
  // normalise
  var total = weights.reduce(function(a,b){ return a+b; }, 0);
  return weights.map(function(w){ return w / total; });
}

// Pragmatic listener model: condition on hearing the bare utterance "fish"
function model(){
  // prior over target objects (uniform over shared context)
  var target = uniformDraw(shared);
  // compute speaker distribution for this target
  var probs = speakerDist(target);
  // find index of the observed utterance "fish"
  var idx = utterances.indexOf("fish");
  // weight by the probability that the speaker would have said "fish"
  factor(Math.log(probs[idx]));
  return target;
}

