function matchesUtterance(u, target){
  var partsU = u.split(" ");
  var partsT = target.split(" ");
  var typeU = partsU.length===1 ? partsU[0] : partsU[1];
  var typeT = partsT[1];
  if (typeU !== typeT) return false;
  if (partsU.length===1) return true; // bare
  var colorU = partsU[0];
  var colorT = partsT[0];
  return colorU === colorT;
}

