var states = [0, 1, 2, 3];
var utterances = ['all', 'some', 'none'];
var alpha = 1;

// Literal meaning function
var literalMeaning = function(utt, state) {
  return (utt === 'all' && state === 3) ||
         (utt === 'some' && state > 0) ||
         (utt === 'none' && state === 0);
};

// Literal listener: given utterance and QUD, samples state and returns QUD value
var literalListener = function(utt, qud) {
  return Infer({method: 'enumerate'}, function() {
    var state = uniformDraw(states);
    var meaning = literalMeaning(utt, state);
    condition(meaning);
    // QUD values: 'all?' is (state === 3), 'any?' is (state > 0)
    return qud === 'all?' ? (state === 3) : (state > 0);
  });
};

// Speaker: given state and QUD, chooses utterance by weighting with literal listener
var speaker = function(state, qud) {
  return Infer({method: 'enumerate'}, function() {
    var utt = uniformDraw(utterances);
    var L0 = literalListener(utt, qud);
    var qudValue = (qud === 'all?' ? (state === 3) : (state > 0));
    factor(alpha * Math.log(L0.score(qudValue)));
    return utt;
  });
};

// Pragmatic listener: given utterance and QUD, infers world state
var pragmaticListener = function(utt, qud) {
  return Infer({method: 'enumerate'}, function() {
    var state = uniformDraw(states);
    var S1 = speaker(state, qud);
    observe(S1, utt);
    return state;
  });
};

