  var literalMeanings = {
    'all': (s) => s === 3,
    'some': (s) => s > 0,
    'none': (s) => s === 0
  };

  function speakerLikelihood(utterance, state) {
    var weights = utterances.map(u => {
      var correct = literalMeanings[u](state);
      var weight = Math.exp(1 * Math.log(correct ? 1.0 : 0.00001));
      return weight;
    });
    var total = weights.reduce((a, b) => a + b, 0);
    return weights[utterances.indexOf(utterance)] / total;
  }

  var p = () => {
    var evidence = 'some';
    var prior = Math.PI / 4; // Approximate uniform over 0-3
    var likelihood = states.reduce((acc, s) => {
      acc[s] = speakerLikelihood(evidence, s);
      return acc;
    }, {});

    var weights = states.map(s => {
      var unnormalized = likelihood[s];
      return unnormalized;
    });

    var sum = weights.reduce((a, b) => a + b, 0);
    var posterior = states.map(s => weights[s] / sum);

    var distribution = categorical(posterior);
    return distribution;
  };

  return p();
});

