  {prediction: 'red', confidence: 'high'},
  {prediction: 'red', confidence: 'high'},
  {prediction: 'blue', confidence: 'low'},
  {prediction: 'blue', confidence: 'low'}
];

// Model definition
var model = function() {
  // Sample pRed from the discrete prior
  var pRed = uniformDraw(priorVals);

  // Condition on the participant's own draw: 4 reds out of 8
  factor(Math.log(binomialPMF(4, 8, pRed)));

  // Incorporate each other agent's report
  reports.forEach(function(r) {
    // Probability of the agent's prediction given the true pRed
    var probPred = (r.prediction === 'red') ? pRed : (1 - pRed);

    // Determine what confidence would be under the model
    var impliedConfidence = ((r.prediction === 'red' && pRed >= 0.6) ||
                             (r.prediction === 'blue' && pRed <= 0.4)) ? 'high' : 'low';

    // If the reported confidence does not match, the likelihood is zero
    if (impliedConfidence !== r.confidence) {
      factor(-Infinity);
    } else {
      // Otherwise weight by the prediction probability
      factor(Math.log(probPred));
    }
  });

  // Return the posterior sample for pRed
  return pRed;
};

