// Helper functions for combinatorics
function factorial(n){ var r=1; for(var i=2;i<=n;i++) r*=i; return r; }
function comb(n,k){ return factorial(n)/(factorial(k)*factorial(n-k)); }
function binomProb(n,k,p){ return comb(n,k) * Math.pow(p,k) * Math.pow(1-p,n-k); }

// Experimental data
var nMarbles = 8;
var selfData = 4;
