// Pre‑compute probability of each report conditioned on the latent red count
// For each agent we build an array probReportX[0..nMarbles]
function reportProbGivenX(x, pred, conf){
  var Z = 0;
  var probs = [];
  for(var i=0;i<prior.length;i++){
    var p = prior[i];
    var w = priorProb[i] * binomProb(nMarbles, x, p);
    probs.push({p:p, w:w});
    Z += w;
  }
  var sum = 0;
  for(var j=0;j<probs.length;j++){
    var p = probs[j].p;
    var w = probs[j].w/Z; // posterior probability of p given x
    var predProb = (pred==='red') ? p : (1-p);
    var high = false;
    if(pred==='red' && p>=0.6) high=true;
    if(pred==='blue' && p<=0.4) high=true;
    if( (conf==='high' && high) || (conf==='low' && !high) ){
      sum += w * predProb;
    }
  }
  return sum;
}

var agentsProbReportX = [];
for(var a=0;a<reports.length;a++){
  var arr = [];
  for(var x=0;x<=nMarbles;x++){
    arr.push(reportProbGivenX(x, reports[a].prediction, reports[a].confidence));
  }
  agentsProbReportX.push(arr);
}

