var prior = categorical(possibleProportions.map((p) => 1/possibleProportions.length));

// Model of other agent
function modelOtherAgent(predicted, confidence, proportion) {
  var Infer = infer;
  var observedRed = (Infer()
    .uniformInt(0, nMarbles)
    .condition((obsRed) => 
      factor(Binomial({n: nMarbles, p: proportion}).pmf(obsRed)))
  );
  var prediction = (observedRed < nMarbles/2 ? 'blue' : 'red');
  var confidenceLevel = (prediction === 'red' && proportion >= confidenceThreshold) ||
                        (prediction === 'blue' && proportion <= 1 - confidenceThreshold) ? 'high' : 'low';
  factor(predicted === prediction && confidence === confidenceLevel ? 1 : 0);
}

// Model for participant's inference
