    var sum = 0;
    for (var i = 0; i <= nMarbles; i++) {
      var likelihood = modelOtherAgent(report.prediction, report.confidence, pRed);
      sum += (Binomial({n: nMarbles, p: pRed}).pmf(i) * likelihood);
    }
    factor(sum);
  });
  return pRed;
});

