// Safe binomial probability
var binomProb = function(k, n, p) {
  var pSafe = Math.max(1e-10, Math.min(1 - 1e-10, p));
  return Math.exp(Binomial({n: n, p: pSafe}).score(k));
};

// Agent's posterior weights over pRedValues given they observed k red out of 8
var agentPosteriorWeights = function(k) {
  var unnorm = map(function(p) { return binomProb(k, nMarbles, p); }, pRedValues);
  var total = sum(unnorm);
  return map(function(u) { return u / total; }, unnorm);
};

// P(prediction, confidence | agent saw k red out of 8)
// Agent predicts 'red' w.p. pRed_agent (their posterior), 'blue' w.p. 1-pRed_agent
// Confidence 'high' if (red & pRed>=0.6) or (blue & pRed<=0.4)
var agentReportProb = function(report, k) {
  var postWeights = agentPosteriorWeights(k);
  var total = sum(mapIndexed(function(i, p) {
    var postProb = postWeights[i];
    var predProb = (report.prediction === 'red') ? p : (1 - p);
    var confIsHigh = (report.prediction === 'red' && p >= 0.6) ||
                     (report.prediction === 'blue' && p <= 0.4);
    var confProb = (report.confidence === 'high') ? (confIsHigh ? 1 : 0)
                                                  : (confIsHigh ? 0 : 1);
    return postProb * predProb * confProb;
  }, pRedValues));
  return total;
};

// Expected log-likelihood of a report given true pRed
// E_{k ~ Binomial(8, pRed)}[log P(report | k)]
var expectedLogLik = function(report, pRed) {
  return sum(map(function(k) {
    var kProb = binomProb(k, nMarbles, pRed);
    var rProb = agentReportProb(report, k);
    return kProb * Math.log(rProb + 1e-300);
  }, kValues));
};

