var utterancePrior = function() {
  return categorical({vs: ['him', 'Fred', 'John'], ps: [2, 1, 1]});
};

var referentPrior = function() {
  return uniformDraw(['John', 'Fred']);
};

var strategyPrior = function() {
  return uniformDraw(['Subject', 'Parallel']);
};

var meaning = function(utterance, referent, strategy) {
  if (utterance === 'him') {
    if (strategy === 'Subject') {
      return referent === 'John';
    } else { // Parallel
      return referent === 'Fred';
    }
  } else if (utterance === 'Fred') {
    return referent === 'Fred';
  } else { // 'John'
    return referent === 'John';
  }
};

var literalListener = function(utterance, strategy) {
  return Infer({method: 'enumerate'}, function() {
    var referent = referentPrior();
    condition(meaning(utterance, referent, strategy));
    return referent;
  });
};

var speaker = function(referent, strategy) {
  return Infer({method: 'enumerate'}, function() {
    var utterance = utterancePrior();
    var listenerProb = Math.exp(literalListener(utterance, strategy).score(referent));
    factor(Math.log(listenerProb));
    return utterance;
  });
};

var pragmaticListener = function(utterance) {
  return Infer({method: 'enumerate'}, function() {
    var referent = referentPrior();
    var strategy = strategyPrior();
    var speakerProb = Math.exp(speaker(referent, strategy).score(utterance));
    factor(Math.log(speakerProb));
    return referent;
  });
};

