var utterances = ['him', 'Fred', 'John'];
var utterancePrior = [2, 1, 1].map(function(x) { return x / sum([2, 1, 1]); });
var referents = ['John', 'Fred'];
var strategies = ['Subject', 'Parallel'];

function resolve(utterance, referent, strategy) {
  if (utterance === 'him') {
    return strategy === 'Subject' ? referent === 'John' : referent === 'Fred';
  } else {
    return utterance === referent;
  }
}

function literalListener(utterance, strategy) {
  var listenerDist = {};
  referents.forEach(function(referent) {
    listenerDist[referent] = resolve(utterance, referent, strategy) ? 1 : 0;
  });
  return normalize(listenerDist);
}

function speaker(referent, strategy) {
  var speakerDist = {};
  utterances.forEach(function(utterance) {
    var prob = utterancePrior[utterances.indexOf(utterance)];
    prob *= literalListener(utterance, strategy)[referent];
    speakerDist[utterance] = prob;
  });
  return normalize(speakerDist);
}

function pragmaticListener(utterance) {
  var dist = {};
  strategies.forEach(function(strategy) {
    referents.forEach(function(referent) {
      var prob = 0.5 * 0.5 * speaker(referent, strategy)[utterance];
      if (!dist[referent]) dist[referent] = 0;
      dist[referent] += prob;
    });
  });
  return normalize(dist);
}

function sum(arr) {
  return arr.reduce(function(a, b) { return a + b; }, 0);
}

function normalize(dist) {
  var total = sum(Object.values(dist));
  return mapObject(dist, function(x) { return x / total; });
}

function mapObject(obj, f) {
  return Object.keys(obj).reduce(function(acc, key) {
    acc[key] = f(obj[key]);
    return acc;
  }, {});
}

