    condition(
      (utterance === "him" && strategy === "Subject" && referent === "John") ||
      (utterance === "him" && strategy === "Parallel" && referent === "Fred") ||
      (utterance !== "him" && referent === utterance)
    );
    return referent;
  });
};

var speaker = function(referent, strategy) {
  return Infer({method: 'enumerate'}, function() {
    var utterance = sample(utterancePrior);
    var llDist = literalListener(utterance, strategy);
    var listenerProb = Math.exp(llDist.score(referent));
    factor(Math.log(listenerProb));
    return utterance;
  });
};

var pragmaticListener = function(utterance) {
  return Infer({method: 'enumerate'}, function() {
    var referent = uniformDraw(referents);
    var strategy = uniformDraw(strategies);
    var speakerDist = speaker(referent, strategy);
    var speakerProb = Math.exp(speakerDist.score(utterance));
    factor(Math.log(speakerProb));
    return referent;
  });
};

