var referents = ["John", "Fred"];
var strategies = ["Subject", "Parallel"];
var referentPrior = { "John": 0.5, "Fred": 0.5 };
var strategyPrior = { "Subject": 0.5, "Parallel": 0.5 };

function getReferent(utterance, strategy) {
  if (utterance === "him") {
    return strategy === "Subject" ? "John" : "Fred";
  }
  return utterance;
}

function literalPosterior(utterance, strategy) {
  var weights = {};
  for (var r of referents) {
    var ref = getReferent(utterance, strategy);
    weights[r] = ref === r ? 0.5 : 0;
  }
  var sum = 0;
  for (var k in weights) sum += weights[k];
  var posterior = {};
  for (var k in weights) posterior[k] = weights[k] / sum;
  return posterior;
}

function speakerProb(utterance, referent, strategy) {
  var literalPost = literalPosterior(utterance, strategy);
  if (!literalPost[referent]) return 0;
  var utteranceUtterance = utterancePrior[utterance];
  return utteranceUtterance * literalPost[referent];
}

function model() {
  var utterance = "him";
  var weights = { "John": 0, "Fred": 0 };
  for (var r of referents) {
    for (var s of strategies) {
      var p = referentPrior[r] * strategyPrior[s] * speakerProb(utterance, r, s);
      weights[r] += p;
    }
  }
  var total = weights["John"] + weights["Fred"];
  weights = { "John": weights["John"] / total, "Fred": weights["Fred"] / total };
  return categorical(weights);
}

