function consistent(variant, name) {
  var a = attrs[name];
  if (variant === "ng") {
    // competence = true OR friendliness = false
    return a.competence === true || a.friendliness === false;
  } else { // "n"
    // competence = false OR friendliness = true
    return a.competence === false || a.friendliness === true;
  }
}

// Literal listener probability P(persona | variant)
function literalProb(name, variant) {
  if (!consistent(variant, name)) return 0;
  var Z = 0;
  personas.forEach(function(p) {
    if (consistent(variant, p)) Z += prior[p];
  });
  return prior[name] / Z;
}

// Speaker probability of choosing a variant given a persona
var alpha = 6;
function speakerProb(variant, name) {
  var variants = ["n", "ng"];
  var scores = variants.map(function(v) {
    var lp = literalProb(name, v);
    // score proportional to (P_literal)^alpha
    return Math.pow(lp, alpha);
  });
  var total = scores[0] + scores[1];
  if (total === 0) return 0;
  var idx = variant === "n" ? 0 : 1;
  return scores[idx] / total;
}

