// Pragmatic listener function
function pragmaticListener(utterance, bins, probs) {
  var expectations = [];
  var thetaExpensives = []; // same as bins
  var thetaInexpensives = [];
  for (var i = 0; i < bins.length; i++) {
    thetaExpensives.push(bins[i]);
