      thetaInexpensives.push(bins[i]);
    } else {
      thetaInexpensives.push(bins[Math.floor(Math.random() * bins.length)]);
    }
  }

  for (var i = 0; i < bins.length; i++) {
    for (var j = 0; j < thetaExpensives.length; j++) {
      var thetaExpensive = thetaExpensives[j];
      var thetaInexpensive = thetaInexpensives[j];
      var speakerProb = speaker(bins[i], thetaExpensive, thetaInexpensive, bins, probs);
      if (utterance === 'expensive') {
        var semanticProb = bins[i] > thetaExpensive ? 0.9999 : 0.0001;
      } else {
        var semanticProb = bins[i] >= thetaInexpensive ? 0.9999 : 0.0001;
      }
      expectations.push({ price: bins[i], prob: probs[i] * semanticProb * speakerProb });
    }
  }

  var norm = expectations.reduce(function(acc, curr) { return acc + curr.prob; }, 0);
  expectations.forEach(function(exp) { exp.prob /= norm; });
  var expectedPrice = expectations.reduce(function(acc, curr) { return acc + curr.price * curr.prob; }, 0);
  return expectedPrice;
}

