data {
  int<lower=0> M;                // Size of augmented data set
  int<lower=0> T;                // Number of sampling occasions
  array[M, T] int<lower=0, upper=1> y; // Capture-history matrix
}
parameters {
  real<lower=0, upper=1> omega;  // inclusion probability
  real<lower=0, upper=1> p;      // detection probability
}
transformed parameters {
  // number of individuals ever captured
  int n_obs;
  // probability of being a real individual given never captured
  real omega_nd;

  n_obs = 0;
  for (i in 1:M) {
    int sum_y = 0;
    for (t in 1:T) sum_y += y[i, t];
    if (sum_y > 0) n_obs += 1;
  }

  // omega_nd = omega * (1-p)^T / [ omega * (1-p)^T + (1-omega) ]
  real term = omega * pow(1 - p, T);
  omega_nd = term / (term + (1 - omega));
}
model {
  // Uniform(0,1) priors are implicit; no explicit prior needed

  // Likelihood
  for (i in 1:M) {
    int sum_y = 0;
    for (t in 1:T) sum_y += y[i, t];
    if (sum_y > 0) {
      // Individual was captured at least once: must be real
      target += sum_y * log(p) + (T - sum_y) * log1m(p);
    } else {
      // Never captured: marginal likelihood
      target += log1m(omega) + log1p( (omega / (1 - omega)) * pow(1 - p, T) );
      // Equivalent to log( 1 - omega + omega * (1-p)^T )
    }
  }
}
generated quantities {
  int N; // estimated total population size
  N = n_obs + binomial_rng(M - n_obs, omega_nd);
}

