  int<lower=0> T; // Number of sampling occasions
  array[M, T] int<lower=0, upper=1> y; // Capture-history matrix
}

parameters {
  real<lower=0, upper=1> omega; // Inclusion probability
  real<lower=0, upper=1> p; // Detection probability
}

transformed parameters {
  real<lower=0, upper=1> omega_nd; // Probability of being present given never detected
  real omega_nd_num = omega * (1 - p)^T;
  real omega_nd_den = omega_nd_num + (1 - omega);
  omega_nd = omega_nd_num / omega_nd_den;

  int<lower=0> N_obs; // Number of observed individuals
  int<lower=0> N_not_obs; // Number of not observed individuals
  N_obs = 0;
  N_not_obs = 0;
  for (m in 1:M) {
    int detected = 0;
    for (t in 1:T) {
      detected += y[m, t];
    }
    if (detected > 0) {
      N_obs += 1;
    } else {
      N_not_obs += 1;
    }
  }

  int<lower=0> N; // Total population size
  N = N_obs + binomial_rng(N_not_obs, omega_nd);
}

model {
  for (m in 1:M) {
    int detected = 0;
    for (t in 1:T) {
      detected += y[m, t];
    }
    if (detected > 0) {
      target += log(omega);
      for (t in 1:T) {
        if (y[m, t] == 1) {
          target += log(p);
        } else {
          target += log(1 - p);
        }
      }
    } else {
      target += log(omega * (1 - p)^T + (1 - omega));
    }
  }
}

data {
  int<lower=0> M; // Size of augumented data set
  int<lower=0> T; // Number of sampling occasions
  array[M, T] int<lower=0, upper=1> y; // Capture-history matrix
}
parameters {
  real<lower=0, upper=1> omega;
  real<lower=0, upper=1> p;
}
transformed parameters {
  real<lower=0, upper=1> omega_nd;
  int<lower=0> N;
  int<lower=0> n_observed = 0;

  // Compute the probability of being present given never detected
  real denom = omega * pow(1 - p, T) + (1 - omega);
  if (denom > 0) {
    omega_nd = omega * pow(1 - p, T) / denom;
  } else {
    omega_nd = 0;
  }

  // Count number of observed individuals (at least one capture)
  for (i in 1:M) {
    int sum_y = 0;
    for (t in 1:T) {
      sum_y += y[i, t];
    }
    if (sum_y > 0) {
      n_observed += 1;
    }
  }

  // Estimate total population size N
  N = n_observed + binomial_rng(M - n_observed, omega_nd);
}
model {
  // Priors (implicit uniform on (0,1) for omega and p)

  // Likelihood contribution from each individual
  for (i in 1:M) {
    int sum_y = 0;
    for (t in 1:T) {
      sum_y += y[i, t];
    }

    if (sum_y > 0) {
      // Individual was captured at least once: must be real
      target += log(omega) + sum_y * log(p) + (T - sum_y) * log(1 - p);
    } else {
      // Individual never captured: could be real (but missed) or phantom
      real pr_real_missed = omega * pow(1 - p, T);
      real pr_phantom = 1 - omega;
      target += log_sum_exp(log(pr_real_missed), log(pr_phantom));
    }
  }
}

data {
  int<lower=0> M; // Size of augumented data set
  int<lower=0> T; // Number of sampling occasions
  array[M, T] int<lower=0, upper=1> y; // Capture-history matrix
}

parameters {
  real<lower=0, upper=1> omega; // Inclusion probability
  real<lower=0, upper=1> p; // Detection probability
}

transformed parameters {
  real<lower=0, upper=1> omega_nd;
  int N;

  int observed = 0;
  for (i in 1:M) {
    if (sum(y[i]) > 0) {
      observed += 1;
    }
  }

  omega_nd = (omega * pow(1 - p, T)) / (omega * pow(1 - p, T) + (1 - omega));

  int unobserved = M - observed;
  int binom_draw = binomial_rng(unobserved, omega_nd);
  N = observed + binom_draw;
}

model {
  // Uniform priors for omega and p
  omega ~ uniform(0, 1);
  p ~ uniform(0, 1);

  // Likelihood for observed individuals (at least one capture)
  for (i in 1:M) {
    int y_count = sum(y[i]);
    if (y_count > 0) {
      target += log(omega) + y_count * log(p) + (T - y_count) * log(1 - p);
    }
  }

  // Likelihood for unobserved individuals (zero captures)
  // These are either real missed individuals or phantom individuals
  // The probability for a specific empty history
  // P(y=0 | omega, p) = omega * (1-p)^T + (1 - omega)
  // We iterate only over unique individuals? No, sum over all data points.
  // The model specifies M candidates.
  // Wait, we need to weight each candidate by P(y[i]|omega,p).
  // If y[i] has all zeros, we add log prob of empty.
  // To optimize, we can count empty rows.
  for (i in 1:M) {
    int y_count = sum(y[i]);
    if (y_count == 0) {
      real prob_zero = omega * pow(1 - p, T) + (1 - omega);
      target += log(prob_zero);
    }
  }
}

