data {
  int<lower=0> M;                // Size of augmented data set
  int<lower=0> T;                // Number of sampling occasions
  array[M, T] int<lower=0, upper=1> y; // Capture-history matrix
}
parameters {
  real<lower=0, upper=1> omega;          // Inclusion probability
  vector<lower=0, upper=1>[T] p;         // Occasion‑specific detection probabilities
}
transformed parameters {
  real pr;                               // Probability of never being captured given presence
  real omega_nd;                         // Probability of being present given never detected
  real N;                                // Estimated total population size

  // product (1 - p[t]) over occasions
  pr = 1;
  for (t in 1:T)
    pr *= (1 - p[t]);

  // conditional probability of being a real individual when never captured
  omega_nd = omega * pr / (omega * pr + (1 - omega));

  // number of individuals ever captured
  int n_observed = 0;
  for (i in 1:M) {
    int sum_y = 0;
    for (t in 1:T)
      sum_y += y[i, t];
    if (sum_y > 0)
      n_observed += 1;
  }

  // expected total population size (deterministic given parameters)
  N = n_observed + (M - n_observed) * omega_nd;
}
model {
  // Marginal likelihood for each individual
  real sum_log1m = 0;
  for (t in 1:T)
    sum_log1m += log1m(p[t]);

  for (i in 1:M) {
    int sum_y = 0;
    for (t in 1:T)
      sum_y += y[i, t];

    if (sum_y > 0) {
      // At least one capture: must be a real individual
      target += log(omega);
      for (t in 1:T) {
        if (y[i, t] == 1)
          target += log(p[t]);
        else
          target += log1m(p[t]);
      }
    } else {
      // No captures: integrate over real vs phantom status
      target += log_sum_exp(log(omega) + sum_log1m,
                            log1m(omega));
    }
  }
}

data {
