  vector<lower=0, upper=1>[3] p;          // Detection probabilities for t=1,2,3
}

transformed_parameters {
  real pr;                 // Probability of never being captured
  real omega_nd;           // Probability of presence given never detected
  int n_captured = 0;      // Number of individuals with at least one capture
  int n_uncaptured;        // Number of individuals never captured
  real N;                  // Estimated total population size

  // Compute product of (1 - p_t)
  pr = 1;
  for (t in 1:3)
    pr *= (1 - p[t]);

  // Count captured and uncaptured individuals
  for (i in 1:M) {
    bool captured = false;
    for (t in 1:3)
      if (y[i, t] == 1) {
        captured = true;
        break;
      }
    if (captured)
      n_captured += 1;
  }
  n_uncaptured = M - n_captured;

  // Compute posterior inclusion probability for those never captured
  omega_nd = omega * pr / (omega * pr + (1 - omega));

  // Estimate total population size as expected value given data
  N = n_captured + n_uncaptured * omega_nd;
}

model {
  // Likelihood
  for (i in 1:M) {
    bool captured = false;
    for (t in 1:3)
      if (y[i, t] == 1) {
        captured = true;
        break;
      }
    if (captured) {
      // Individual is known real member
      for (t in 1:3)
        target += bernoulli_lpmf(y[i, t] | p[t]);
    } else {
      // Individual may be real or phantom
      target += log(omega * pr + (1 - omega));
    }
