data {
  int<lower=0> M; // Size of augmented data set
  int<lower=0> T; // Number of sampling occasions
  array[M, T] int<lower=0, upper=1> y; // Capture-history matrix
}

parameters {
  real<lower=0, upper=1> omega; // Inclusion probability
  array[T] real<lower=0, upper=1> p; // Detection probabilities
}

transformed parameters {
  real pr; // Probability of never being captured given presence
  real omega_nd; // Probability of being present given never detected
  real<lower=0> N; // Estimated total population size

  // Calculate pr = product of (1 - p_t) for all occasions
  pr = 1.0;
  for (t in 1:T) {
    pr *= (1.0 - p[t]);
  }

  // Calculate omega_nd = omega * pr / (omega * pr + (1 - omega))
  omega_nd = (omega * pr) / (omega * pr + (1.0 - omega));

  // Calculate estimated population size
  N = 0.0;
  for (i in 1:M) {
    int ever_captured = 0;
    for (t in 1:T) {
      ever_captured += y[i, t];
    }
    if (ever_captured == 0) {
      N += omega_nd;
    } else {
      N += 1.0;
    }
  }
}

model {
  // Likelihood
  for (i in 1:M) {
    // Check if individual i was ever captured
    int ever_captured = 0;
    for (t in 1:T) {
      ever_captured += y[i, t];
    }

    if (ever_captured == 0) {
      // Never captured: P(y[i]) = omega * pr + (1 - omega)
      target += log(omega * pr + (1.0 - omega));
    } else {
      // Captured at least once
      real log_like_real = 0.0;
      for (t in 1:T) {
        if (y[i, t] == 1) {
          log_like_real += log(p[t]);
        } else {
          log_like_real += log(1.0 - p[t]);
        }
      }
      // P(y[i]) = omega * product of p_t^y[i,t] * (1-p_t)^(1-y[i,t])
      target += log(omega) + log_like_real;
    }
  }
}

data {
