  real<lower=0, upper=1> pr; // Probability of never being captured given presence
  real<lower=0, upper=1> omega_nd; // Probability of being present given never detected
  real<lower=0> N; // Estimated total population size

  pr = 1;
  for (t in 1:T) {
    pr *= (1 - p[t]);
  }

  omega_nd = omega * pr / (omega * pr + (1 - omega));

  N = M * omega / (1 - pr);
}

model {
  omega ~ uniform(0, 1);
  p ~ uniform(0, 1);

  for (i in 1:M) {
    real<lower=0, upper=1> prob_real = omega;
    real<lower=0, upper=1> prob_phantom = 1 - omega;

    real log_prob_real = log(omega);
    real log_prob_phantom = log(1 - omega);

    for (t in 1:T) {
      if (y[i, t] == 1) {
        log_prob_real += log(p[t]);
        log_prob_phantom += log(0);
      } else {
        log_prob_real += log(1 - p[t]);
        log_prob_phantom += log(1);
      }
    }

    target += log_sum_exp(log_prob_real, log_prob_phantom);
  }
}

