}
transformed parameters {
  real pr;
  real omega_nd;
  real N;

  // Probability of never being captured given presence
  // product of (1 - p_t) over all T occasions
  pr = 1.0;
  for (t in 1:T) {
    pr = pr * (1.0 - p[t]);
  }

  // Probability of being present given never detected
  // omega_nd = P(z=1 | y=0) = (omega * pr) / (omega * pr + (1 - omega))
  // Denominator is P(y=0) = P(y=0|z=1)*P(z=1) + P(y=0|z=0)*P(z=0)
  omega_nd = (omega * pr) / (omega * pr + 1.0 - omega);

  // Estimated total population size N
  // Expected number of real individuals in the augmented set of size M
  N = M * omega;
}
model {
  // Prior distributions
  // omega and p_t have implicit Uniform(0, 1) prior
  omega ~ uniform(0, 1);
  for (t in 1:T) {
    p[t] ~ uniform(0, 1);
  }

  // Marginalized likelihood
  for (i in 1:M) {
    // Sum of captures for individual i to check if detected
    int captures = 0;
    for (t in 1:T) {
      captures = captures + y[i, t];
    }

    if (captures > 0) {
      // Detected at least once -> must be real (membership z=1)
      // Probability is P(y_i | z_i=1) * P(z_i=1)
      // = (product over t of Bern(y_{it} | p_t)) * omega
      target += log(omega);
      for (t in 1:T) {
        if (y[i, t] == 1) {
          target += log(p[t]);
        } else {
          target += log(1.0 - p[t]);
        }
      }
    } else {
      // Never detected -> could be real or phantom (z=0 or z=1)
      // Probability is P(y_i | z_i=1)*P(z_i=1) + P(y_i | z_i=0)*P(z_i=0)
      // = omega * prod(1-p_t) + (1 - omega)
      target += log(omega * pr + 1.0 - omega);
    }
  }
}

data {
  int<lower=0> M; // Size of augumented data set
  int<lower=0> T; // Number of sampling occasions
  array[M, T] int<lower=0, upper=1> y; // Capture-history matrix
}

parameters {
  real<lower=0, upper=1> omega;
  vector<lower=0, upper=1>[T] p;
}

transformed parameters {
  real<lower=0, upper=1> pr;
  real<lower=0, upper=1> omega_nd;

  {
    real tmp = 1.0;
    for (t in 1:T) {
      tmp *= (1.0 - p[t]);
    }
    pr = tmp;
  }

  omega_nd = (omega * pr) / (omega * pr + (1.0 - omega));
}

model {
  // omega ~ Uniform(0, 1) implicit
  // p[t] ~ Uniform(0, 1) implicit

  for (i in 1:M) {
    int ever_captured = 0;
    for (t in 1:T) {
      if (y[i, t] == 1) {
        ever_captured = 1;
        break;
      }
    }

    if (ever_captured == 1) {
      // Must be a real individual (z_i = 1)
      real lp = log(omega);
      for (t in 1:T) {
        lp += bernoulli_lpmf(y[i, t] | p[t]);
      }
      target += lp;
    } else {
      // Either real and never detected, or a phantom
      real lp_real    = log(omega) + log(pr);
      real lp_phantom = log1m(omega);
      target += log_sum_exp(lp_real, lp_phantom);
    }
  }
}

generated quantities {
  real<lower=0> N;
  {
    int z_sum = 0;
    for (i in 1:M) {
      int ever_captured = 0;
      for (t in 1:T) {
        if (y[i, t] == 1) {
          ever_captured = 1;
          break;
        }
      }
      if (ever_captured == 1) {
        z_sum += 1;
      } else {
        // Draw z_i from its posterior: Bernoulli(omega_nd)
        z_sum += bernoulli_rng(omega_nd);
      }
    }
    N = z_sum;
  }
}

