model {
  vector[n_count] log_terms;
  for (i in 1:n_count) {
    int n = n_start + i - 1;
    // uniform prior on n
    real log_prior_n = -log(n_count);
    real log_like = 0;
    for (j in 1:m) {
      log_like += binomial_lpmf(k[j] | n, theta);
