    if (k[i] > n_min)
      n_min = k[i];
  }

  real log_lik_sum = negative_infinity();
  real log_prior_n = log(1.0 / (nmax - n_min + 1));

  for (n in n_min : nmax) {
    real log_lik_n = log_prior_n;
    for (i in 1:m)
      log_lik_n += binomial_lpmf(k[i] | n, theta);
    log_lik_sum = log_sum_exp(log_lik_sum, log_lik_n);
  }

  target += log_lik_sum;
