  vector[n_range] log_probs;

  for (i in 1:n_range) {
    int n = n_min + i - 1;

    // Log prior on n (discrete uniform from n_min to nmax)
    real log_prior_n = -log(n_range);

    // Log likelihood: product of binomials for each observation
    real log_lik = 0;
    for (j in 1:m) {
      log_lik += binomial_lpmf(k[j] | n, theta);
