}
parameters {
  real<lower=0, upper=1> theta;
}
transformed parameters {
  // The marginal likelihood over n is computed and used for inference on theta
  // n ranges from max(k) to nmax, with discrete uniform prior
  int<lower=0> kmax = max(k);
  vector[nmax - kmax + 1] log_p_n;  // log probabilities for each possible n
  real log_p_theta = 0;  // placeholder, not directly used

  // Compute log likelihood for each possible n, marginalizing over n
  for (i in 1:(nmax - kmax + 1)) {
    int n = kmax + i - 1;
    log_p_n[i] = 0;  // log prior for n is uniform, so constant (ignored in rel terms)
    // Add log likelihood for all m observations
    for (j in 1:m) {
      log_p_n[i] += binomial_lpmf(k[j] | n, theta);
    }
  }
  // Marginal log likelihood for theta: log_sum_exp over n
  target += log_sum_exp(log_p_n);
}
model {
  // Prior on theta
  theta ~ uniform(0, 1);
}

data {
  int<lower=0> nmax;
  int<lower=0> m;
  array[m] int<lower=0, upper=nmax> k;
}

parameters {
  real<lower=0, upper=1> theta;
}

model {
  // Uniform(0,1) prior on theta has zero log density
  target += 0;

  // Find maximum observed return count across all occasions
  real max_k = k[1];
  for (i in 2:m) {
    if (k[i] > max_k) {
      max_k = k[i];
    }
  }

  // Number of possible n values (n from max_k to nmax)
  int n_count = nmax - max_k + 1;

  // Prior for discrete n is uniform over the valid range
  // Log prior contribution per support point is -log(n_count)
  real log_prior_n = -log(n_count);

  // Marginalize over n by summing joint densities: P(k,theta,n)
  for (n in max_k:nmax) {
    // Add log prior for discrete n
    target += log_prior_n;

    // Add log likelihood: product of Binomial(k[i] | n, theta) across occasions
    for (i in 1:m) {
      // log Binomial(k[i] | n, theta)
      target += lgamma(n + 1) - lgamma(k[i] + 1) - lgamma(n - k[i] + 1);
      target += k[i] * log(theta);
      target += (n - k[i]) * log(1 - theta);
    }
  }
}

data {
  int<lower=0> nmax;
  int<lower=0> m;
  array[m] int<lower=0, upper=nmax> k;
}

parameters {
  real<lower=0, upper=1> theta;
}

model {
  // theta ~ uniform(0, 1) is implicit from the declared bounds

  // Marginalize over n from max(k) to nmax
  int k_max = max(k);
  int n_range = nmax - k_max + 1;

  // Build log weights for each candidate value of n
  vector[n_range] log_w;
  for (j in 1:n_range) {
    int n = k_max + j - 1;
    real lp = 0.0;
    for (i in 1:m) {
      lp += binomial_lpmf(k[i] | n, theta);
    }
    log_w[j] = lp;
  }

  // The discrete uniform prior on n contributes a constant -log(n_range),
  // which does not affect inference on theta and is omitted.
  target += log_sum_exp(log_w);
}

