data {
  int<lower=1> K;          // number of states
  int<lower=1> N;          // length of process
  array[N] real u;         // 1/speed
  array[N] real v;         // hoop distance
  matrix<lower=0>[K, K] alpha; // transition Dirichlet hyperparameters
}
parameters {
  simplex[K] theta1;               // transition probs from state 1
  simplex[K] theta2;               // transition probs from state 2
  ordered<lower=0>[K] phi;         // exponential rates for u (phi[1] <= phi[2])
  ordered<lower=0>[K] lambda;      // exponential rates for v (lambda[1] <= lambda[2])
}
model {
  // priors on transition matrices
  theta1 ~ dirichlet(to_vector(alpha[1]));
  theta2 ~ dirichlet(to_vector(alpha[2]));

  // half‑normal priors on rate parameters
  phi[1]   ~ normal(0, 1);
  phi[2]   ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // forward algorithm for HMM marginal likelihood
  vector[K] log_alpha;          // log‑forward probabilities at current time
  vector[K] log_alpha_next;     // temporary storage

  // initial step (uniform initial distribution)
  for (k in 1:K) {
    log_alpha[k] = log(1.0 / K)
                 + exponential_lpdf(u[1] | phi[k])
                 + exponential_lpdf(v[1] | lambda[k]);
  }

  // recursion for t = 2,…,N
  for (t in 2:N) {
    for (k in 1:K) {
      vector[K] tmp;
      for (j in 1:K) {
        real trans_prob = (j == 1) ? theta1[k] : theta2[k];
        tmp[j] = log_alpha[j] + log(trans_prob);
      }
      log_alpha_next[k] = log_sum_exp(tmp)
                        + exponential_lpdf(u[t] | phi[k])
                        + exponential_lpdf(v[t] | lambda[k]);
    }
    log_alpha = log_alpha_next;
  }

  // marginal log‑likelihood
  target += log_sum_exp(log_alpha);
}

functions {
  /* helper to compute log-sum-exp for two scalars */
  real log_sum_exp_two(real a, real b) {
    if (a > b)
      return a + log1p(exp(b - a));
    else
      return b + log1p(exp(a - b));
  }
}

data {
  int<lower=1> K;          // number of states (K = 2)
  int<lower=1> N;          // length of process
  array[N] real u;         // 1/speed
  array[N] real v;         // hoop distance
  matrix<lower=0>[K, K] alpha; // transition prior (dirichlet hyper‑parameters)
}

parameters {
  simplex[2] theta1;               // transition probs from state 1
  simplex[2] theta2;               // transition probs from state 2

  ordered[2] real<lower=0> phi;    // emission rates for u      (phi[1] <= phi[2])
  ordered[2] real<lower=0> lambda; // emission rates for v      (lambda[1] <= lambda[2])
}

model {
  /* Transition priors */
  theta1 ~ dirichlet(alpha[1]);
  theta2 ~ dirichlet(alpha[2]);

  /* Emission priors (half‑normal, with ordering automatically enforced) */
  phi[1] ~ normal(0, 1);
  phi[2] ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  /* Forward algorithm for the HMM likelihood */
  vector[2] alpha;          // log‐unnormalized forward probabilities
  vector[2] next;

  // Initial state (uniformly over the two states)
  alpha[1] = log(0.5) + exponential_lpdf(u[1] | phi[1]) + exponential_lpdf(v[1] | lambda[1]);
  alpha[2] = log(0.5) + exponential_lpdf(u[1] | phi[2]) + exponential_lpdf(v[1] | lambda[2]);

  for (t in 2:N) {
    for (k in 1:2) {
      // Transition probability from previous states to current state k
      vector[2] trans_log;
      trans_log[1] = alpha[1] + log(theta1[k]); // from state 1
      trans_log[2] = alpha[2] + log(theta2[k]); // from state 2
      // Forward update for state k at time t
      next[k] = log_sum_exp_two(trans_log[1], trans_log[2])
                + exponential_lpdf(u[t] | phi[k])
                + exponential_lpdf(v[t] | lambda[k]);
    }
    alpha = next;
  }

  // Log evidence for the observed data
  target += log_sum_exp_two(alpha[1], alpha[2]);
}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
}

parameters {
  simplex[K] theta1;
  simplex[K] theta2;
  ordered[K] phi;  // phi[1] <= phi[2]
  ordered[K] lambda;  // lambda[1] <= lambda[2]
}

model {
  // Priors
  theta1 ~ dirichlet(alpha[1, ]');
  theta2 ~ dirichlet(alpha[2, ]');

  phi[1] ~ normal(0, 1);
  phi[2] ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // Likelihood using forward algorithm (marginalize out hidden states)
  vector[K] log_alpha = rep_vector(-log(K), K); // log(1/K) for uniform initial state

  // Add observation probabilities at t=1
  for (k in 1:K) {
    log_alpha[k] += exponential_lpdf(u[1] | phi[k]) + exponential_lpdf(v[1] | lambda[k]);
  }

  // Forward pass for t = 2, ..., N
  for (t in 2:N) {
    vector[K] log_alpha_new;

    for (k in 1:K) {
      // Transition probabilities to state k from each previous state
      vector[K] trans_to_k;
      trans_to_k[1] = log(theta1[k]);
      trans_to_k[2] = log(theta2[k]);

      // Forward probability: sum over previous states with transition probabilities
      log_alpha_new[k] = log_sum_exp(log_alpha + trans_to_k);

      // Add observation probability at time t
      log_alpha_new[k] += exponential_lpdf(u[t] | phi[k]) + exponential_lpdf(v[t] | lambda[k]);
    }

    log_alpha = log_alpha_new;
  }

  // Total likelihood contribution
  target += log_sum_exp(log_alpha);
}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
}

parameters {
  simplex[K] theta1; // transition probabilities from state 1
  simplex[K] theta2; // transition probabilities from state 2
  real<lower=0> phi_raw1; // exponential rate parameter for inverse speed in state 1
  real<lower=0> phi_raw2; // exponential rate parameter for inverse speed in state 2
  real<lower=0> lambda_raw1; // exponential rate parameter for hoop distance in state 1
  real<lower=0> lambda_raw2; // exponential rate parameter for hoop distance in state 2
}

transformed parameters {
  real<lower=0> phi[2];
  real<lower=0> lambda[2];

  phi[1] = phi_raw1;
  phi[2] = phi_raw2 + phi[1];
  lambda[1] = lambda_raw1;
  lambda[2] = lambda_raw2 + lambda[1];
}

model {
  // Priors
  theta1 ~ dirichlet(alpha[1, :]);
  theta2 ~ dirichlet(alpha[2, :]);
  phi_raw1 ~ normal(0, 1);
  phi_raw2 ~ normal(3, 1);
  lambda_raw1 ~ normal(0, 1);
  lambda_raw2 ~ normal(3, 1);

  // Initialize hidden Markov model
  real gamma[N, K];
  {
    real init[K];
    init[1] = 0.5;
    init[2] = 0.5;
    gamma[1, 1] = init[1] * exp(-u[1] * phi[1]) * exp(-v[1] * lambda[1]);
    gamma[1, 2] = init[2] * exp(-u[1] * phi[2]) * exp(-v[1] * lambda[2]);
    for (n in 2:N) {
      gamma[n, 1] = (gamma[n - 1, 1] * theta1[1] + gamma[n - 1, 2] * theta2[1]) * exp(-u[n] * phi[1]) * exp(-v[n] * lambda[1]);
      gamma[n, 2] = (gamma[n - 1, 1] * theta1[2] + gamma[n - 1, 2] * theta2[2]) * exp(-u[n] * phi[2]) * exp(-v[n] * lambda[2]);
    }
  }

  // Normalize
  for (n in 1:N) {
    gamma[n, 1] = gamma[n, 1] / (gamma[n, 1] + gamma[n, 2]);
    gamma[n, 2] = gamma[n, 2] / (gamma[n, 1] + gamma[n, 2]);
  }

  // Marginal likelihood
  target += log(gamma[N, 1] + gamma[N, 2]);
}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
}
parameters {
  simplex[K] theta1;
  simplex[K] theta2;
  ordered[K] phi;
  ordered[K] lambda;
}
model {
  // Priors
  theta1 ~ dirichlet(alpha[1,]);
  theta2 ~ dirichlet(alpha[2,]);
  phi[1] ~ normal(0, 1);
  phi[2] ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // HMM forward algorithm
  array[N] real z_logp; // log probability of hidden state at each time
  array[N] vector[K] log_alpha; // forward variables

  // Initialize at t=1: uniform over states
  log_alpha[1, 1] = -log(K) + exponential_lpdf(u[1] | phi[1]) + exponential_lpdf(v[1] | lambda[1]);
  log_alpha[1, 2] = -log(K) + exponential_lpdf(u[1] | phi[2]) + exponential_lpdf(v[1] | lambda[2]);

  // Forward pass
  for (t in 2:N) {
    for (k in 1:K) {
      log_alpha[t, k] = log_sum_exp(log_alpha[t-1, 1] + log(theta1[k]),
                                    log_alpha[t-1, 2] + log(theta2[k])) +
                        exponential_lpdf(u[t] | phi[k]) +
                        exponential_lpdf(v[t] | lambda[k]);
    }
  }

  // Total log probability
  target += log_sum_exp(log_alpha[N]);
}

data {
  int<lower=1> K;
  int<lower=1> N;
  array[N] real u;
  array[N] real v;
  matrix<lower=0>[K, K] alpha;
}

parameters {
  simplex[K] theta1;
  simplex[K] theta2;
  ordered[K] phi;
  ordered[K] lambda;
  int<lower=1, upper=K> z[N];
}

model {
  theta1 ~ dirichlet(alpha[1]);
  theta2 ~ dirichlet(alpha[2]);

  for (k in 1:K) {
    phi[k] ~ normal((k == 1 ? 0 : 3), 1);
    lambda[k] ~ normal((k == 1 ? 0 : 3), 1);
  }

  target -= log(K);

  for (t in 2:N) {
    if (z[t-1] == 1) {
      target += log(theta1[z[t]]);
    } else {
      target += log(theta2[z[t]]);
    }
  }

  for (t in 1:N) {
    target += exponential_lpdf(u[t] | phi[z[t]]);
    target += exponential_lpdf(v[t] | lambda[z[t]]);
  }
}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
}

parameters {
  simplex[K] theta1;
  positive_ordered[K] phi;
  positive_ordered[K] lambda;
  simplex[K] theta2;
}

model {
  // Priors on transition probabilities
  theta1 ~ dirichlet(to_vector(alpha[1]));
  theta2 ~ dirichlet(to_vector(alpha[2]));

  // Half-normal priors on emission rate parameters
  phi[1]    ~ normal(0, 1);
  phi[2]    ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // Build log transition matrix: log_A[j, k] = log P(z_t = k | z_{t-1} = j)
  matrix[K, K] log_A;
  for (k in 1:K) {
    log_A[1, k] = log(theta1[k]);
    log_A[2, k] = log(theta2[k]);
  }

  // Forward algorithm (log scale) to marginalise over hidden states
  vector[K] log_fwd;

  // Initialise at t = 1 with uniform state prior
  for (k in 1:K) {
    log_fwd[k] = log(1.0 / K)
                 + exponential_lpdf(u[1] | phi[k])
                 + exponential_lpdf(v[1] | lambda[k]);
  }

  // Recursion for t = 2, ..., N
  for (t in 2:N) {
    vector[K] log_fwd_new;
    for (k in 1:K) {
      real emit_k = exponential_lpdf(u[t] | phi[k])
                    + exponential_lpdf(v[t] | lambda[k]);
      vector[K] lp;
      for (j in 1:K) {
        lp[j] = log_fwd[j] + log_A[j, k];
      }
      log_fwd_new[k] = log_sum_exp(lp) + emit_k;
    }
    log_fwd = log_fwd_new;
  }

  // Add marginal log-likelihood
  target += log_sum_exp(log_fwd);
}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
  real<lower=0> tau; // sd u
  real<lower=0> rho; // sd v
}

parameters {
  simplex[2] theta1;          // transition probabilities from state 1
  simplex[2] theta2;          // transition probabilities from state 2
  ordered[2] phi;             // emission means for u (phi[1] <= phi[2])
  ordered[2] lambda;          // emission means for v (lambda[1] <= lambda[2])
}

model {
  // Dirichlet priors for transition rows
  target += dirichlet_lpdf(theta1 | to_vector(alpha[1]));
  target += dirichlet_lpdf(theta2 | to_vector(alpha[2]));

  // Priors for emission means
  target += normal_lpdf(phi[1]   | 0, 1);
  target += normal_lpdf(phi[2]   | 3, 1);
  target += normal_lpdf(lambda[1]| 0, 1);
  target += normal_lpdf(lambda[2]| 3, 1);

  // Log of transition matrices (rows = previous state, cols = next state)
  matrix[2, 2] log_trans;
  for (j in 1:2) {
    for (k in 1:2) {
      if (j == 1)
        log_trans[j, k] = log(theta1[k]);
      else
        log_trans[j, k] = log(theta2[k]);
    }
  }

  // Forward algorithm (log‑scale)
  matrix[N, 2] f_log;
  // initial step (equal prior over the two states)
  f_log[1, 1] = log(0.5)
                + normal_lpdf(u[1] | phi[1],     tau)
                + normal_lpdf(v[1] | lambda[1], rho);
  f_log[1, 2] = log(0.5)
                + normal_lpdf(u[1] | phi[2],     tau)
                + normal_lpdf(v[1] | lambda[2], rho);

  for (t in 2:N) {
    for (k in 1:2) {
      f_log[t, k] = log_sum_exp(f_log[t-1, 1] + log_trans[1, k],
                                f_log[t-1, 2] + log_trans[2, k])
                    + normal_lpdf(u[t] | phi[k],     tau)
                    + normal_lpdf(v[t] | lambda[k], rho);
    }
  }

  // marginal likelihood
  target += log_sum_exp(f_log[N, 1], f_log[N, 2]);
}

data {
  int<lower=1> K;                  // number of states (1 = none, 2 = drive)
  int<lower=1> N;                  // length of process
  array[N] real u;                 // 1/speed
  array[N] real v;                 // hoop distance
  matrix<lower=0>[K, K] alpha;     // transition prior
  real<lower=0> tau;               // sd u
  real<lower=0> rho;               // sd v
}
parameters {
  simplex[2] theta1;    // transition probs from state 1
  simplex[2] theta2;    // transition probs from state 2
  ordered[2] phi;       // emission means for u
  ordered[2] lambda;    // emission means for v
}
model {
  // Prior on transition probabilities
  theta1 ~ dirichlet(alpha[1]);
  theta2 ~ dirichlet(alpha[2]);

  // Priors on emission means
  phi[1] ~ normal(0, 1);
  phi[2] ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // Forward algorithm for log-likelihood
  vector[2] a_prev;

  // t = 1: initial equal probability 0.5
  a_prev[1] = log(0.5) + normal_lpdf(u[1] | phi[1], tau)
                        + normal_lpdf(v[1] | lambda[1], rho);
  a_prev[2] = log(0.5) + normal_lpdf(u[1] | phi[2], tau)
                        + normal_lpdf(v[1] | lambda[2], rho);

  for (t in 2:N) {
    vector[2] a_new;
    for (j in 1:2) { // current state j
      vector[2] log_trans;
      for (i in 1:2) { // previous state i
        if (i == 1)
          log_trans[i] = a_prev[i] + log(theta1[j]);
        else
          log_trans[i] = a_prev[i] + log(theta2[j]);
      }
      a_new[j] = log_sum_exp(log_trans)
                 + normal_lpdf(u[t] | phi[j], tau)
                 + normal_lpdf(v[t] | lambda[j], rho);
    }
    a_prev = a_new;
  }

  target += log_sum_exp(a_prev);
}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
  real<lower=0> tau; // sd u
  real<lower=0> rho; // sd v
}

parameters {
  simplex[K] theta1;
  simplex[K] theta2;
  ordered[K] phi;
  ordered[K] lambda;
}

model {
  // Priors
  theta1 ~ dirichlet(alpha[1]);
  theta2 ~ dirichlet(alpha[2]);
  phi[1] ~ normal(0, 1);
  phi[2] ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // HMM forward algorithm
  vector[K] log_alpha = rep_vector(-log(K), K); // uniform initial state

  for (t in 1:N) {
    vector[K] log_lik;
    for (k in 1:K) {
      log_lik[k] = normal_lpdf(u[t] | phi[k], tau) + normal_lpdf(v[t] | lambda[k], rho);
    }

    vector[K] log_alpha_new;
    for (j in 1:K) {
      vector[K] log_trans = [log(theta1[j]), log(theta2[j])]';
      log_alpha_new[j] = log_sum_exp(log_alpha + log_trans) + log_lik[j];
    }
    log_alpha = log_alpha_new;
  }

  target += log_sum_exp(log_alpha);
}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
  real<lower=0> tau; // sd u
  real<lower=0> rho; // sd v
}

parameters {
  simplex[K] theta1; // transit probabilities out of state 1
  simplex[K] theta2; // transit probabilities out of state 2
  real<lower=-3> phi1; // emission mean for u in state 1
  real<lower=phi1> phi2; // emission mean for u in state 2
  real<lower=-3> lambda1; // emission mean for v in state 1
  real<lower=lambda1> lambda2; // emission mean for v in state 2
}

model {
  theta1 ~ dirichlet(alpha[1]);
  theta2 ~ dirichlet(alpha[2]);
  phi1 ~ normal(0, 1);
  phi2 ~ normal(3, 1);
  lambda1 ~ normal(0, 1);
  lambda2 ~ normal(3, 1);

  {
    array[N] real log_p_state;
    log_p_state[1] = log(0.5) + normal_lpdf(u[1] | phi1, tau) + normal_lpdf(v[1] | lambda1, rho);
    log_p_state[1] = log_sum_exp(log_p_state[1], log(0.5) + normal_lpdf(u[1] | phi2, tau) + normal_lpdf(v[1] | lambda2, rho));

    for (n in 2:N) {
      log_p_state[n] = log_sum_exp(
        log_p_state[n - 1] + log(theta1[1]) + normal_lpdf(u[n] | phi1, tau) + normal_lpdf(v[n] | lambda1, rho),
        log_p_state[n - 1] + log(theta1[2]) + normal_lpdf(u[n] | phi2, tau) + normal_lpdf(v[n] | lambda2, rho),
        log_p_state[n - 1] + log(theta2[1]) + normal_lpdf(u[n] | phi1, tau) + normal_lpdf(v[n] | lambda1, rho),
        log_p_state[n - 1] + log(theta2[2]) + normal_lpdf(u[n] | phi2, tau) + normal_lpdf(v[n] | lambda2, rho)
      );
    }

    target += log_p_state[N];
  }
}

transformed parameters {
  real theta11 = theta1[1];
  real theta12 = theta1[2];
  real theta21 = theta2[1];
  real theta22 = theta2[2];
  real phi_1 = phi1;
  real phi_2 = phi2;
  real lambda_1 = lambda1;
