}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
  real<lower=0> tau; // sd u
  real<lower=0> rho; // sd v
}
parameters {
  simplex[K] theta1;
  simplex[K] theta2;
  ordered[K] phi;
  ordered[K] lambda;
}
transformed parameters {
  // Combine transition probabilities into a matrix for easier indexing
  simplex[K] theta[K];
  theta[1] = theta1;
  theta[2] = theta2;
}
model {
  // Priors
  theta1 ~ dirichlet(alpha[1]);
  theta2 ~ dirichlet(alpha[2]);
  phi[1] ~ normal(0, 1);
  phi[2] ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // Forward algorithm for HMM
  {
    real acc[K];
    real log_sum;
    array[N] real lp;
    array[K] real gamma;

    // Initialization
    for (k in 1:K) {
      gamma[k] = normal_lpdf(u[1] | phi[k], tau) + normal_lpdf(v[1] | lambda[k], rho);
      acc[k] = log(1.0 / K) + gamma[k];
    }
    log_sum = log_sum_exp(acc);
    lp[1] = log_sum;

    // Forward pass
    for (t in 2:N) {
      for (k in 1:K) {
        for (j in 1:K) {
          acc[j] = log(theta[j, k]) + acc[j];
        }
        gamma[k] = normal_lpdf(u[t] | phi[k], tau) + normal_lpdf(v[t] | lambda[k], rho);
        acc[k] = log_sum_exp(acc) + gamma[k];
      }
      log_sum = log_sum_exp(acc);
      lp[t] = log_sum;

      // Normalize to prevent underflow
      for (k in 1:K) {
        acc[k] -= log_sum;
      }
    }

    target += sum(lp);
  }
}

data {
  int<lower=1> K;
  int<lower=1> N;
  array[N] real u;
  array[N] real v;
  matrix<lower=0>[K, K] alpha;
  real<lower=0> tau;
  real<lower=0> rho;
}
parameters {
  simplex[K] theta1;
  simplex[K] theta2;
  ordered[K] phi;
  ordered[K] lambda;
  array[N] int<lower=1,upper=K> z;
}
model {
  // Dirichlet priors on transition matrices (alpha row k for transitions from state k)
  theta1 ~ dirichlet(alpha[1, ]);
  theta2 ~ dirichlet(alpha[2, ]);

  // Normal priors on emission means
  phi[1] ~ normal(0, 1);
  phi[2] ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // Uniform prior over K states for initial state
  target += log(1.0 / K);

  // Transition likelihood
  for (t in 2:N) {
    if (z[t-1] == 1) {
      target += log(theta1[z[t]]);
    } else {
      target += log(theta2[z[t]]);
    }
  }

  // Emission likelihood
  for (t in 1:N) {
    target += normal_lpdf(u[t] | phi[z[t]], tau);
    target += normal_lpdf(v[t] | lambda[z[t]], rho);
  }
}

data {
  int<lower=1> K; // number of states (1 = none, 2 = drive)
  int<lower=1> N; // length of process
  array[N] real u; // 1/speed
  array[N] real v; // hoop distance
  matrix<lower=0>[K, K] alpha; // transit prior
  real<lower=0> tau; // sd u
  real<lower=0> rho; // sd v
}

parameters {
  simplex[K] theta1;
  simplex[K] theta2;
  ordered[K] phi;
  ordered[K] lambda;
}

model {
  // Priors on transition probabilities
  theta1 ~ dirichlet(to_vector(alpha[1]));
  theta2 ~ dirichlet(to_vector(alpha[2]));

  // Priors on emission means
  phi[1] ~ normal(0, 1);
  phi[2] ~ normal(3, 1);
  lambda[1] ~ normal(0, 1);
  lambda[2] ~ normal(3, 1);

  // Forward algorithm to marginalize over hidden states
  // log_fwd[t, k] = log P(u[1..t], v[1..t], z[t] = k)
  matrix[N, K] log_fwd;

  // Initialise at t = 1 with uniform initial distribution
  for (k in 1:K) {
    log_fwd[1, k] = log(1.0 / K)
      + normal_lpdf(u[1] | phi[k], tau)
      + normal_lpdf(v[1] | lambda[k], rho);
  }

  // Recursion for t = 2 .. N
  for (t in 2:N) {
    for (k in 1:K) {
      // Contributions from each previous state j
      // P(z[t]=k | z[t-1]=1) = theta1[k]
      // P(z[t]=k | z[t-1]=2) = theta2[k]
      vector[K] lp;
      lp[1] = log_fwd[t - 1, 1] + log(theta1[k]);
      lp[2] = log_fwd[t - 1, 2] + log(theta2[k]);
      log_fwd[t, k] = log_sum_exp(lp)
        + normal_lpdf(u[t] | phi[k], tau)
        + normal_lpdf(v[t] | lambda[k], rho);
    }
  }

  // Marginal log-likelihood: sum over terminal states
  target += log_sum_exp(log_fwd[N]);
}

data {
  int<lower=0> nChild;
  int<lower=0> nInd;
  array[nInd, 4] real gamma; // -1 if missing
  array[nInd] real delta;
  array[nInd] int<lower=0> ncat;
  array[nChild, nInd] int grade; // -1 if missing
}
parameters {
  vector[nChild] theta;
}
model {
  // prior for latent ages
  theta ~ normal(0, 36);

  // likelihood
  for (i in 1:nChild) {
    for (j in 1:nInd) {
      int g = grade[i, j];
      if (g != -1) {                         // observed grade
        int nc = ncat[j];                    // number of categories for indicator j
        // handle the (unlikely) case of a single-category indicator
        if (nc == 1) {
          if (g != 1) target += negative_infinity();
          continue;
        }

        // compute cumulative probabilities Q_{j,k}
        vector[nc - 1] Q;
        for (k in 1:(nc - 1)) {
          // assume gamma[j, k] is valid (non‑missing) for k <= nc‑1
          Q[k] = inv_logit(delta[j] * (theta[i] - gamma[j, k]));
        }

        // compute probability of the observed grade
        real p;
        if (g == 1) {
          p = 1 - Q[1];
        } else if (g == nc) {
          p = Q[nc - 1];
        } else {
          p = Q[g - 1] - Q[g];
        }
        target += log(p);
      }
    }
  }
}

data {
  int<lower=0> nChild;
  int<lower=0> nInd;
  array[nInd, 4] real gamma; // -1 if missing
  array[nInd] real delta;
  array[nInd] int<lower=0> ncat;
  array[nChild, nInd] int grade; // -1 if missing
}

parameters {
  vector[nChild] theta;
}

model {
  // prior on latent ages
  theta ~ normal(0, 36);

  int g;
  int ncat_j;
  int kmax;
  vector[4] Q;  // maximum number of thresholds is 4

  for (i in 1:nChild)
    for (j in 1:nInd) {
      g = grade[i, j];
      if (g == -1) continue;          // missing observation
      ncat_j = ncat[j];
      kmax = ncat_j - 1;               // number of thresholds

      for (k in 1:kmax)
        Q[k] = inv_logit(delta[j] * (theta[i] - gamma[j, k]));

      if (g == 1)
        target += log1m(Q[1]);                             // log(1 - Q1)
      else if (g == ncat_j)
        target += log(Q[kmax]);                            // log(Q_last)
      else
        target += log(Q[g - 1] - Q[g]);                    // log(Q_{g-1} - Q_g)
    }
}

data {
  int<lower=0> nChild;
  int<lower=0> nInd;
  array[nInd, 4] real gamma; // -1 if missing
  array[nInd] real delta;
  array[nInd] int<lower=0> ncat;
  array[nChild, nInd] int grade; // -1 if missing
}

parameters {
  vector[nChild] theta;
}

model {
  // Prior on latent skeletal ages
  theta ~ normal(0, 36);

  // Likelihood
  for (i in 1:nChild) {
    for (j in 1:nInd) {
      if (grade[i, j] != -1) {  // Only process non-missing observations
        int g = grade[i, j];
        int K = ncat[j];
        vector[K] prob;

        if (K == 1) {
          // If only one category, probability is 1
          prob[1] = 1;
        } else {
          // Compute cumulative probabilities Q_{j,k} for k = 1, ..., K-1
          vector[K-1] Q;
          for (k in 1:(K-1)) {
            Q[k] = inv_logit(delta[j] * (theta[i] - gamma[j, k]));
          }

          // Compute category probabilities from cumulative probabilities
          // P(grade = 1) = 1 - Q_{j,1}
          prob[1] = 1 - Q[1];

          // P(grade = k) = Q_{j,k-1} - Q_{j,k} for k = 2, ..., K-1
          for (k in 2:(K-1)) {
            prob[k] = Q[k-1] - Q[k];
          }

          // P(grade = K) = Q_{j,K-1}
          prob[K] = Q[K-1];
        }

        // Likelihood contribution
        grade[i, j] ~ categorical(prob);
      }
    }
  }
}

data {
  int<lower=0> nChild;
  int<lower=0> nInd;
  array[nInd, 4] real gamma; // -1 if missing
  array[nInd] real delta;
  array[nInd] int<lower=0> ncat;
  array[nChild, nInd] int grade; // -1 if missing
}

parameters {
  real theta[13];
}

model {
  theta ~ normal(0, 36);
  for (i in 1:nChild) {
    for (j in 1:nInd) {
      if (grade[i, j] != -1) {
        vector[ncat[j] - 1] Q;
        vector[ncat[j]] P;
        for (k in 1:ncat[j] - 1) {
          if (gamma[j, k] != -1) {
            Q[k] = inv_logit(delta[j] * (theta[i] - gamma[j, k]));
          } else {
            Q[k] = 0;
          }
        }
        P[1] = 1 - Q[1];
        for (k in 2:ncat[j] - 1) {
          P[k] = Q[k - 1] - Q[k];
        }
        P[ncat[j]] = Q[ncat[j] - 1];
        if (grade[i, j] == 1) {
          target += log(P[1]);
        } else if (grade[i, j] == ncat[j]) {
          target += log(P[ncat[j]]);
        } else {
          target += log(P[grade[i, j]]);
        }
      }
    }
  }
}

data {
  int<lower=0> nChild;
  int<lower=0> nInd;
  array[nInd, 4] real gamma; // -1 if missing
  array[nInd] real delta;
  array[nInd] int<lower=0> ncat;
  array[nChild, nInd] int grade; // -1 if missing
}
parameters {
  vector[nChild] theta;
}
model {
  // Prior on latent ages
  theta ~ normal(0, 36);

  // Likelihood
  for (i in 1:nChild) {
    for (j in 1:nInd) {
      if (grade[i, j] != -1) {
        // Extract thresholds for indicator j
        vector[ncat[j] - 1] thresholds;
        for (k in 1:(ncat[j] - 1)) {
          thresholds[k] = gamma[j, k];
        }

        // Compute cumulative probabilities
        vector[ncat[j] - 1] cum_prob;
        for (k in 1:(ncat[j] - 1)) {
          cum_prob[k] = inv_logit(delta[j] * (theta[i] - thresholds[k]));
        }

        // Compute category probabilities from cumulative probabilities
        vector[ncat[j]] cat_prob;
        cat_prob[1] = 1 - cum_prob[1];
        for (k in 2:(ncat[j] - 1)) {
          cat_prob[k] = cum_prob[k - 1] - cum_prob[k];
        }
        cat_prob[ncat[j]] = cum_prob[ncat[j] - 1];

        // Contribute to likelihood
        target += log(cat_prob[grade[i, j]]);
      }
    }
  }
}

data {
  int<lower=0> nChild;
  int<lower=0> nInd;
  array[nInd, 4] real gamma; // -1 if missing
  array[nInd] real delta;
  array[nInd] int<lower=0> ncat;
  array[nChild, nInd] int grade; // -1 if missing
}

parameters {
  vector[nChild] theta;
}

model {
  theta ~ normal(0, 36);

  for (i in 1:nChild) {
    for (j in 1:nInd) {
      int g = grade[i, j];
      if (g == -1) continue;

      int n = ncat[j];
      // Allocate Q vector for cumulative probabilities Q[1, ..., n-1]
      vector[n - 1] Q;

      // Initialize Q if size > 0
      if (n > 1) {
        Q = rep_vector(1.0, n - 1); // Placeholder initialization

        for (k in 1:n - 1) {
          if (k <= 4) {
            real val = gamma[j, k];
            if (val != -1) {
              Q[k] = inv_logit(delta[j] * (theta[i] - val));
            }
            // If val == -1, we leave Q[k] as placeholder (handled safely below)
          }
        }
      }

      // Calculate probability mass for observed grade g
      real prob;
      if (n == 1) {
        prob = 1.0;
      } else if (g == 1) {
        // P(grade = 1) = 1 - Q[1]
        // Ensure Q[1] is computed (checked above, if n>1 Q[1] is set by loop)
        prob = 1.0 - Q[1];
      } else if (g == n) {
        // P(grade = n) = Q[n-1]
        prob = Q[n - 1];
      } else {
        // P(grade = k) = Q[k-1] - Q[k]
        // g is between 2 and n-1
        prob = Q[g - 1] - Q[g];
      }

      if (prob > 0) {
        target += log(prob);
      }
    }
  }
}

data {
  int<lower=0> nChild;
  int<lower=0> nInd;
  array[nInd, 4] real gamma; // -1 if missing
  array[nInd] real delta;
  array[nInd] int<lower=0> ncat;
  array[nChild, nInd] int grade; // -1 if missing
}

parameters {
  vector[nChild] theta;
}

model {
  // Prior on latent skeletal ages
  theta ~ normal(0, 36);

  // Likelihood
  for (i in 1:nChild) {
    for (j in 1:nInd) {
      if (grade[i, j] != -1) {
        int g  = grade[i, j];
        int nc = ncat[j];
        real d = delta[j];

        if (nc == 1) {
          // Only one category: probability is 1, contributes 0 to log-likelihood
          target += 0;
        } else if (g == 1) {
          // P(grade = 1) = 1 - Q_{j,1}
          target += log1m_inv_logit(d * (theta[i] - gamma[j, 1]));
        } else if (g == nc) {
          // P(grade = nc) = Q_{j, nc-1}
          target += log_inv_logit(d * (theta[i] - gamma[j, nc - 1]));
        } else {
          // P(grade = g) = Q_{j,g-1} - Q_{j,g}  for 1 < g < nc
          real lq_prev = log_inv_logit(d * (theta[i] - gamma[j, g - 1]));
          real lq_curr = log_inv_logit(d * (theta[i] - gamma[j, g]));
          target += log_diff_exp(lq_prev, lq_curr);
        }
      }
    }
  }
}

data {
  int<lower=1> N;            // number of observations
  vector[N] Y;               // response variable
  int<lower=1> K;            // number of population-level effects (including intercept)
  matrix[N, K] X;            // design matrix (first column = 1s)
  int prior_only;            // if 1, ignore likelihood
}

transformed data {
  int Kc = K - 1;                         // number of centered predictors (should be 24)
  matrix[N, Kc] X_centered;
  vector[Kc] col_means;

  // compute column means for columns 2:K
  for (j in 1:Kc) {
    col_means[j] = mean(X[, j + 1]);
  }

  // centre the predictors
  for (i in 1:N) {
    for (j in 1:Kc) {
      X_centered[i, j] = X[i, j + 1] - col_means[j];
    }
  }
}

parameters {
  vector[24] b;            // regression coefficients for centered predictors
  real Intercept;          // intercept
  real<lower=0> sigma;     // residual standard deviation
}

model {
  // priors
  b ~ normal(0, 1);
  Intercept ~ student_t(3, 8, 10);
  sigma ~ student_t(3, 0, 10);   // half‑Student‑t due to lower=0

  // likelihood (optional)
  if (prior_only == 0) {
    vector[N] mu = Intercept + X_centered * b;
    Y ~ normal(mu, sigma);
  }
}

data {
  int<lower=1> N;          // number of observations
  vector[N] Y;             // response variable
  int<lower=1> K;          // number of population-level effects
  matrix[N, K] X;          // population-level design matrix
  int prior_only;          // flag to ignore the likelihood
}

parameters {
  vector[24] b;              // regression coefficients for the 24 centered predictors
  real Intercept;            // intercept parameter
  real<lower=0> sigma;       // residual standard deviation
}

model {
  matrix[N, 24] X_std = X[, 2:K];          // centered predictors (columns 2 to K)

  // Priors
  b ~ normal(0, 1);
  Intercept ~ student_t(3, 8, 10);
  sigma ~ student_t(3, 0, 10);

  // Likelihood (unless prior_only flag is set)
  if (!prior_only) {
    target += normal_lpdf(Y | Intercept + X_std * b, sigma);
  }
}

data {
  int<lower=1> N; // number of observations
  vector[N] Y; // response variable
  int<lower=1> K; // number of population-level effects
  matrix[N, K] X; // population-level design matrix
  int prior_only; // should the likelihood be ignored?
}

parameters {
  vector[24] b; // regression coefficients for centered predictors
  real Intercept; // intercept
  real<lower=0> sigma; // residual standard deviation
}

model {
  // Priors
  b ~ normal(0, 1); // Independent N(0, 1) priors for b[1] through b[24]
  Intercept ~ student_t(3, 8, 10); // Student-t(3, 8, 10) prior for intercept
  sigma ~ student_t(3, 0, 10); // Half-Student-t(3, 0, 10) prior for sigma

  // Likelihood (conditional on prior_only flag)
  if (!prior_only) {
    Y ~ normal(Intercept + X[, 2:K] * b, sigma);
  }
}

data {
  int<lower=1> N; // number of observations
  vector[N] Y; // response variable
  int<lower=1> K; // number of population-level effects
  matrix[N, K] X; // population-level design matrix
  int prior_only; // should the likelihood be ignored?
}

transformed data {
  vector[K-1] col_means;
  for (i in 2:K) {
