  beta[2] = beta_2;
}
model {
  // Priors
  beta_1 ~ uniform(-100, 0);
  beta_2 ~ uniform(0, 100);

  // Likelihood
  for (i in 1:n_dogs) {
    int a = 0; // number of prior avoidances
    int s = 0; // number of prior shocks
    for (t in 1:n_trials) {
      if (t > 1) {
        if (y[i, t-1] == 1) {
          a += 1;
        } else {
          s += 1;
        }
      }
      real eta = beta_1 * a + beta_2 * s;
      real p = inv_logit(eta);
      y[i, t] ~ bernoulli(p);
    }
  }
}

