  matrix[2, 2] trans_mat;
  trans_mat[1] = theta1';
  trans_mat[2] = theta2';

  // forward algorithm (log‑space) for the marginal likelihood
  vector[2] log_alpha_prev;
  vector[2] log_alpha_curr;

  // initial state distribution: uniform over states
  real log_initial = -log(to_vector(K));  // log(1/K)

  // time 1
  for (j in 1:2) {
    log_alpha_prev[j] = log_initial + normal_lpdf(y[1] | mu[j], 1);
  }

  // times 2..N
  for (t in 2:N) {
    for (j in 1:2) {
      vector[2] log_terms;
      for (i in 1:2) {
        log_terms[i] = log_alpha_prev[i] + log(trans_mat[i, j]);
      }
      log_alpha_curr[j] = log_sum_exp(log_terms) + normal_lpdf(y[t] | mu[j], 1);
    }
    log_alpha_prev = log_alpha_curr;
  }

  // marginal log‑likelihood
  target += log_sum_exp(log_alpha_prev);
}

