  mu[1] ~ normal(3, 1);
  mu[2] ~ normal(10, 1);

  // Ordering constraint: enforce mu[1] <= mu[2]
  if (mu[1] > mu[2]) target += negative_infinity();

  // Forward algorithm for the marginal likelihood of the observations
  vector[K] log_alpha;

  // Initial state distribution: uniform over the two states
  for (j in 1:K) {
    log_alpha[j] = log(0.5) + normal_lpdf(y[1] | mu[j], 1);
  }

  // Iterate the forward recursion
  for (t in 2:N) {
    vector[K] new_alpha;
    for (j in 1:K) {
      // Log probability of coming into state j from either previous state
      real from1 = log_alpha[1] + log(theta1[j]);
      real from2 = log_alpha[2] + log(theta2[j]);

      // Add emission likelihood for the current observation
      new_alpha[j] = log_sum_exp(from1, from2) + normal_lpdf(y[t] | mu[j], 1);
    }
    log_alpha = new_alpha;
  }

  // Add the log marginal likelihood to the total log posterior
  target += log_sum_exp(log_alpha[1], log_alpha[2]);
}

