  real z[N, 2];
  z[1, 1] = z_init[1];
  z[1, 2] = z_init[2];

  for (n in 1:N) {
    real z_new[2];

    // Lotka-Volterra system with numerical integration (using a simple Euler method here, for simplicity)
    z_new[1] = z[n, 1] + (theta[1] - theta[2]*z[n, 2])*z[n, 1]*(ts[n]-ts[n-1]);
    z_new[2] = z[n, 2] + (-theta[3] + theta[4]*z[n, 1])*z[n, 2]*(ts[n]-ts[n-1]);

    z[n+1, 1] = z_new[1];
    z[n+1, 2] = z_new[2];

    // likelihood for observed populations at each time point
    y[n, 1] ~ lognormal(log(z[n, 1]), sigma[1]);
    y[n, 2] ~ lognormal(log(z[n, 2]), sigma[2]);
  }
}

functions {
  array[2] real lotka_volterra(real t, array[2] real z, array[4] real theta) {
    real u = z[1];
    real v = z[2];
    real alpha = theta[1];
    real beta = theta[2];
    real gamma = theta[3];
    real delta = theta[4];
    return {(alpha - beta * v) * u, (-gamma + delta * u) * v};
  }
}
