  sigma_2 ~ normal(0, 2);

  // Prior for theta (Beta(5, 5))
  theta ~ beta(5, 5);

  // Mixture likelihood
  for (n in 1:N) {
    target += log_sum_exp(
      log(theta + numeric_constant(1e-300)) * normal_lpdf(y[n] | mu_1, sigma_1),
      log(1 - theta + numeric_constant(1e-300)) * normal_lpdf(y[n] | mu_2, sigma_2)
    );
  }
}

