data {
  int<lower=1> N;                // number of observations
  vector[N] Y;                   // response variable
  // data related to mean GP
  int<lower=1> Kgp_1;
  int<lower=1> Dgp_1;            // GP dimension
  int<lower=1> NBgp_1;           // number of basis functions
  matrix[N, NBgp_1] Xgp_1;       // basis matrix
  array[NBgp_1] vector[Dgp_1] slambda_1; // eigenvalues
  // data related to variance GP
  int<lower=1> Kgp_sigma_1;
  int<lower=1> Dgp_sigma_1;
  int<lower=1> NBgp_sigma_1;
  matrix[N, NBgp_sigma_1] Xgp_sigma_1;
  array[NBgp_sigma_1] vector[Dgp_sigma_1] slambda_sigma_1;
  int prior_only;               // if 1, ignore likelihood
}

parameters {
  real Intercept;
  real<lower=0> sdgp_1;
  real<lower=0> lscale_1;
  vector[40] zgp_1;                // latent coefficients for mean GP
  real Intercept_sigma;
  real<lower=0> sdgp_sigma_1;
  real<lower=0> lscale_sigma_1;
  vector[20] zgp_sigma_1;          // latent coefficients for variance GP
}

transformed parameters {
  // extract scalar eigenvalues (assume first dimension is relevant)
  vector[NBgp_1] lambda_1;
  for (j in 1:NBgp_1)
    lambda_1[j] = slambda_1[j][1];

  vector[NBgp_sigma_1] lambda_sigma_1;
  for (j in 1:NBgp_sigma_1)
    lambda_sigma_1[j] = slambda_sigma_1[j][1];

  // scaling for each basis according to marginal sd and length‑scale
  vector[NBgp_1] scale_1 = sdgp_1 * exp(-0.5 * lscale_1 * lambda_1);
  vector[NBgp_sigma_1] scale_sigma_1 = sdgp_sigma_1 * exp(-0.5 * lscale_sigma_1 * lambda_sigma_1);

  // latent smooth functions
  vector[N] f_mean = Intercept + Xgp_1 * (zgp_1 .* scale_1);
  vector[N] log_sigma = Intercept_sigma + Xgp_sigma_1 * (zgp_sigma_1 .* scale_sigma_1);
  vector[N] sigma = exp(log_sigma);
}

model {
  // priors
  Intercept ~ student_t(3, -13, 36);
  sdgp_1 ~ student_t(3, 0, 36);
  lscale_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_1 ~ normal(0, 1);

  Intercept_sigma ~ student_t(3, 0, 10);
  sdgp_sigma_1 ~ student_t(3, 0, 36);
  lscale_sigma_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_sigma_1 ~ normal(0, 1);

  // likelihood (skip if prior_only is set)
  if (prior_only == 0) {
    Y ~ normal(f_mean, sigma);
  }
}

