  vector[NBgp_1] sqrt_slambda_1;
  vector[NBgp_sigma_1] sqrt_slambda_sigma_1;
  for (i in 1:NBgp_1)
    sqrt_slambda_1[i] = sqrt(slambda_1[i][1]);

  for (i in 1:NBgp_sigma_1)
    sqrt_slambda_sigma_1[i] = sqrt(slambda_sigma_1[i][1]);

  vector[N] mean_f = Xgp_1 * (sqrt_slambda_1 .* zgp_1);
  vector[N] log_std_f = Xgp_sigma_1 * (sqrt_slambda_sigma_1 .* zgp_sigma_1);

  mu = Intercept + mean_f;
