  vector[N] Y;
  int<lower=1> Kgp_1;
  int<lower=1> Dgp_1;
  int<lower=1> NBgp_1;
  matrix[N, NBgp_1] Xgp_1;
  array[NBgp_1] vector[Dgp_1] slambda_1;
  int<lower=1> Kgp_sigma_1;
  int<lower=1> Dgp_sigma_1;
  int<lower=1> NBgp_sigma_1;
  matrix[N, NBgp_sigma_1] Xgp_sigma_1;
  array[NBgp_sigma_1] vector[Dgp_sigma_1] slambda_sigma_1;
  int prior_only;
}

parameters {
  real Intercept;
  real<lower=0> sdgp_1;
  real<lower=0> lscale_1;
  vector[NBgp_1] zgp_1;
  real Intercept_sigma;
  real<lower=0> sdgp_sigma_1;
  real<lower=0> lscale_sigma_1;
  vector[NBgp_sigma_1] zgp_sigma_1;
}

model {
  // Priors for mean GP
  Intercept ~ student_t(3, -13, 36);
  sdgp_1 ~ student_t(3, 0, 36);
  lscale_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_1 ~ normal(0, 1);

  // Priors for variance GP
  Intercept_sigma ~ student_t(3, 0, 10);
  sdgp_sigma_1 ~ student_t(3, 0, 36);
  lscale_sigma_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_sigma_1 ~ normal(0, 1);

  // Likelihood
  if (!prior_only) {
    vector[N] mu;
    vector[N] sigma;

    // Compute mean function
    for (n in 1:N) {
      mu[n] = Intercept;
      for (k in 1:NBgp_1) {
        mu[n] += Xgp_1[n, k] * sdgp_1 * sqrt(slambda_1[k, 1]) * 
                 exp(-0.5 * lscale_1 * slambda_1[k, 1]) * zgp_1[k];
      }
    }

    // Compute log-variance function and transform to standard deviation
    for (n in 1:N) {
      real log_sigma_raw = Intercept_sigma;
      for (k in 1:NBgp_sigma_1) {
        log_sigma_raw += Xgp_sigma_1[n, k] * sdgp_sigma_1 * sqrt(slambda_sigma_1[k, 1]) * 
                         exp(-0.5 * lscale_sigma_1 * slambda_sigma_1[k, 1]) * zgp_sigma_1[k];
      }
      sigma[n] = exp(log_sigma_raw);
    }

    // Likelihood
    Y ~ normal(mu, sigma);
  }
}

