  real<lower=0> lscale_1;
  vector[NBgp_1] zgp_1;
  real Intercept_sigma;
  real<lower=0> sdgp_sigma_1;
  real<lower=0> lscale_sigma_1;
  vector[NBgp_sigma_1] zgp_sigma_1;
}

model {
  // Priors
  Intercept ~ student_t(3, -13, 36);
  sdgp_1 ~ student_t(3, 0, 36) T[0,];
  lscale_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_1 ~ std_normal();
  Intercept_sigma ~ student_t(3, 0, 10);
  sdgp_sigma_1 ~ student_t(3, 0, 36) T[0,];
  lscale_sigma_1 ~ inv_gamma(1.124909, 0.0177);
  zgp_sigma_1 ~ std_normal();

  // Compute spectral GP variances
  vector[NBgp_1] lambda_1;
  vector[NBgp_sigma_1] lambda_sigma_1;
  for (j in 1:NBgp_1) {
    lambda_1[j] = square(sdgp_1) * exp(-slambda_1[j][1] * square(lscale_1));
  }
  for (j in 1:NBgp_sigma_1) {
    lambda_sigma_1[j] = square(sdgp_sigma_1) * exp(-slambda_sigma_1[j][1] * square(lscale_sigma_1));
  }

  // Compute latent functions
  vector[N] f_mean = Intercept + Xgp_1 * (zgp_1 .* sqrt(lambda_1));
  vector[N] f_sigma = Intercept_sigma + Xgp_sigma_1 * (zgp_sigma_1 .* sqrt(lambda_sigma_1));

  // Likelihood
  if (prior_only == 0) {
    Y ~ normal(f_mean, exp(f_sigma));
  }
}

