functions {
  vector diagSPD_cov_exp_quad(real sdgp, real lscale,
                               array[] vector slambda,
                               int Dgp, int NBgp) {
    vector[NBgp] out;
    real constant = square(sdgp) * pow(sqrt(2.0 * pi()) * lscale, Dgp);
    for (m in 1:NBgp) {
      out[m] = sqrt(constant * exp(-0.5 * square(lscale) * dot_self(slambda[m])));
    }
    return out;
  }
}

