functions {
  vector ode_pk(real t,
                vector y,
                real[] theta,
                real[] x_r,
                int[] x_i) {
    // theta[1] = k_a, theta[2] = K_m, theta[3] = V_m
    // x_r[1] = D,    x_r[2] = V
    real k_a = theta[1];
    real K_m = theta[2];
    real V_m = theta[3];
    real D   = x_r[1];
    real V   = x_r[2];
    real C   = y[1];

    real dC_dt = (k_a * D / V) * exp(-k_a * t)
                 - (V_m / V) * C / (K_m + C);

    vector[1] dy;
    dy[1] = dC_dt;
    return dy;
  }
}
data {
  real t0; // Initial time in days;
  // This is currently hardcoded in data transformations
  // Uncomment this line to get original model
  // real C0[1]; // Initial concentration at t0 in mg/L

  real D; // Total dosage in mg
  real V; // Compartment volume in L

  int<lower=1> N_t;
  array[N_t] real times; // Measurement times in days

  // Measured concentrations in effect compartment in mg/L
  array[N_t] real C_hat;
}
parameters {
  real<lower=0> k_a;   // absorption rate constant
  real<lower=0> K_m;   // Michaelis-Menten half-saturation constant
  real<lower=0> V_m;   // maximum elimination rate
  real<lower=0> sigma; // measurement error standard deviation (log‐scale)
}
transformed parameters {
  array[N_t] real C_pred;          // model predicted concentrations
  vector[1] y0 = rep_vector(0.0, 1); // initial concentration (zero)
  real theta[3];
  real x_r[2];
  int x_i[0];

  theta[1] = k_a;
  theta[2] = K_m;
  theta[3] = V_m;
  x_r[1] = D;
  x_r[2] = V;

  // Solve ODE at the measurement times
  array[N_t] vector[1] y_hat = integrate_ode_rk45(
    ode_pk, y0, t0, times, theta, x_r, x_i
  );

  for (i in 1:N_t) {
    C_pred[i] = y_hat[i][1];
  }
}
model {
  // Half‑Cauchy(0,1) priors
  target += cauchy_lpdf(k_a | 0, 1) + log(2);
  target += cauchy_lpdf(K_m | 0, 1) + log(2);
  target += cauchy_lpdf(V_m | 0, 1) + log(2);
  target += cauchy_lpdf(sigma | 0, 1) + log(2);

  // Likelihood: lognormal observation model
  for (i in 1:N_t) {
    // avoid taking log of non‑positive predictions
    target += lognormal_lpdf(C_hat[i] | log(C_pred[i]), sigma);
  }
}

functions {
  real[] pk_ode(real t, real[] y, real[] theta, real[] x_r, int[] x_i) {
    // State
    real C = y[1];
    // Parameters
    real k_a = theta[1];
    real K_m = theta[2];
    real V_m = theta[3];
    // Constants
    real D = x_r[1];
    real V = x_r[2];
    // Absorption term
    real absorption = k_a * D * exp(-k_a * t) / V;
    // Saturable elimination term
    real elimination = (V_m / V) * C / (K_m + C);
    return [absorption - elimination];
  }
}

