functions {
  // ODE system for one-compartment PK model with first-order absorption
  // and Michaelis-Menten elimination
  array[1] real pk_ode(array[1] real y, real t, array[1] real theta, 
                       data real[] x_r, data int[] x_i) {
    real C = y[1];
    real k_a = theta[1];
    real K_m = theta[2];
    real V_m = theta[3];
    real D = x_i[1]; // passed as integer but we'll cast; better to pass via real
    real V = x_i[2];

    // Absorption rate: first-order from depot compartment
    // We assume D is the amount in depot, so absorption rate is k_a * D * exp(-k_a * t)
    // But we need to express depot amount dynamically — better to model both compartments
    // However, the problem states: absorption is first-order with rate k_a, decaying exponentially
    // So we model the absorption input as: dC/dt += (k_a * D * exp(-k_a * (t - t0))) / V
    // But that assumes no depot compartment ODE. For accuracy, we should solve two ODEs.

    // But the model description implies: the rate of change of concentration
    // includes absorption (exponentially decaying input) and elimination.
    // So: dC/dt = (k_a * D / V) * exp(-k_a * (t - t0)) - (V_m / V) * C / (K_m + C)

    real dC_dt = (k_a * D / V) * exp(-k_a * (t - t0)) - (V_m / V) * C / (K_m + C);

    return {dC_dt};
  }

  // Alternative: two-compartment ODE (depot and central)
  // Depot: A_d, Central: C
  // dA_d/dt = -k_a * A_d
  // dC/dt = (k_a * A_d)/V - (V_m * C)/(V * (K_m + C))
  // Initial: A_d(t0) = D, C(t0) = 0
  array[2] real pk_ode_2c(real t, array[2] real y, array[1] real theta, 
                          data real[] x_r, data int[] x_i) {
    real A_d = y[1];
    real C = y[2];
    real k_a = theta[1];
    real K_m = theta[2];
    real V_m = theta[3];
    real V = x_r[1];  // pass V as real data

    real dAd_dt = -k_a * A_d;
    real dC_dt = (k_a * A_d) / V - (V_m * C) / (V * (K_m + C));

    return {dAd_dt, dC_dt};
  }
}

parameters {
  real<lower=0> k_a;
  real<lower=0> K_m;
  real<lower=0> V_m;
  real<lower=0> sigma;
}

transformed parameters {
  // Solve the ODE system
  array[N_t] real C_pred;
  {
    array[1] real theta = {k_a, K_m, V_m};
    // We'll use the two-compartment model for accuracy
    array[2] real y0 = {D, C0}; // A_d(t0) = D, C(t0) = 0
    array[N_t] array[2] real y_hat;

    // Solve ODE from t0 to each time point
    // We'll use ode_rk45 for each time interval
    y_hat = ode_rk45(pk_ode_2c, y0, t0, times, theta, {V}, {0});

    // Extract predicted concentration (second state)
    for (i in 1:N_t) {
      C_pred[i] = y_hat[i][2];
    }
  }
}

model {
  // Priors
  k_a ~ cauchy(0, 1);
  K_m ~ cauchy(0, 1);
  V_m ~ cauchy(0, 1);
  sigma ~ cauchy(0, 1);

  // Likelihood: lognormal around predicted concentration
  // The problem states: lognormal with log-mean = log(C_pred) and sd = sigma
  // So: log(C_hat) ~ normal(log(C_pred), sigma)
  // But we must handle C_pred > 0; if C_pred is 0, log fails.
  // Our ODE should prevent exact zero after t0, but near zero is possible.
  // We assume C_pred > 0 due to absorption.
  for (i in 1:N_t) {
    target += lognormal_lpdf(C_hat[i] | log(C_pred[i]), sigma);
  }
}

functions {
  real odefun(real t, real y, real[] theta, real[] x_r, real y_r) {
    real k_a = theta[1];
    real K_m = theta[2];
    real V_m = theta[3];

    real D = x_r[1];
    real V = x_r[2];

    // First-order absorption
    real absorption_rate = k_a * (D / V) * exp(-k_a * t);
    // Saturable Michaelis-Menten elimination
    real elimination_rate = V_m * y / (K_m + y);

    return absorption_rate - elimination_rate;
  }
}

