var model = function() {
  // Stable niceness trait drawn once
  var nice = flip(0.7);

  // Probability of wanting given niceness
  var pWants = nice ? 0.2 : 0.5;

  // Niceness channel fire probability
  var pNiceChannel = nice ? 0.8 : 0.5;

  // Helper: probability of smiling given wants and niceness
  var smileProb = function(wants) {
    var pWantChannel = wants ? 0.8 : 0.5;
    // Smile = OR of two independent channels
    return 1 - (1 - pWantChannel) * (1 - pNiceChannel);
  };

  // Five past days of not smiling
  var pastDays = 5;
  var logPastLikelihood = function(numDays) {
    if (numDays === 0) return 0;
    // Each day, wanting drawn independently from prior
    // Marginal P(not smile) = sum over wants of P(wants)*P(not smile | wants, nice)
    var pNotSmile = pWants * (1 - smileProb(true)) + (1 - pWants) * (1 - smileProb(false));
    return numDays * Math.log(pNotSmile);
  };

  factor(logPastLikelihood(5));

  // Today: draw wanting independently
  var wantsToday = flip(pWants);

  // Observe smiling today
  var pSmileToday = smileProb(wantsToday);
  factor(Math.log(pSmileToday));

  return wantsToday;
};

